DG.put("krisnaavtaar/53",{"n":53,"title":null,"title_roman":null,"page":519,"blocks":[{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":519},{"type":"verse","number":[1136],"number_text":"੧੧੩੬।","page":519,"lines":[{"gurmukhi":"ਅਣਗ ਸਿੰਘ ਅਉ ਅਚਲ ਸੀ ਅਮਿਤ ਸਿੰਘ ਨ੍ਰਿਪ ਤੀਰ।","roman":"Anag singh au achal see amit singh nrip teer |","meaning_en":"","page":519},{"gurmukhi":"ਅਮਰ ਸਿੰਘ ਅਰ ਅਨਘ ਸੀ ਮਹਾਰਥੀ ਰਨਧੀਰ। ੧੧੩੬।","roman":"Amar singh ar anagh see mahaarthee randheer | 1136 |","meaning_en":"","page":519}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":519},{"type":"verse","number":[1137],"number_text":"੧੧੩੭।","page":519,"lines":[{"gurmukhi":"ਦੇਖਿ ਤਿਨੈ ਨ੍ਰਿਪ ਸੰਧਿ ਜਰਾ ਹਥੀਆਰ ਧਰੇ ਲਖਿ ਬੀਰ ਪਚਾਰੇ।","roman":"Dekhi tinai nrip sandhi jaraa hatheeaar dhare lakhi beer pachaare |","meaning_en":"","page":519},{"gurmukhi":"ਪੇਖਹੁ ਆਜ ਅਯੋਧਨ ਮੈ ਨ੍ਰਿਪ ਪੰਚ ਬਲੀ ਜਦੁਬੀਰ ਸੰਘਾਰੇ।","roman":"Pekhhu aaj ayodhan mai nrip panch balee jadubeer sanghaare |","meaning_en":"","page":519},{"gurmukhi":"ਤਾ ਸੰਗਿ ਜਾਇ ਭਿਰੋ ਤੁਮ ਹੂੰ ਤਜਿ ਸੰਕ ਨਿਸੰਕ ਬਜਾਇ ਨਗਾਰੇ।","roman":"Taa sangi jaai bhiro tum hoon taji sank nisank bajaai nagaare |","meaning_en":"","page":519},{"gurmukhi":"ਯੌ ਸੁਨਿ ਕੈ ਪ੍ਰਭ ਕੀ ਬਤੀਯਾ ਅਤਿ ਕੋਪ ਭਰੇ ਰਨ ਓਰਿ ਪਧਾਰੇ। ੧੧੩੭।","roman":"Yau suni kai prabh kee bateeyaa ati kop bhare ran ori padhaare | 1137 |","meaning_en":"","page":519}]},{"type":"verse","number":[1138],"number_text":"੧੧੩੮।","page":519,"lines":[{"gurmukhi":"ਆਵਤ ਹੀ ਜਦੁਬੀਰ ਤਿਨੋ ਰਨ ਭੂਮਿ ਬਿਖੈ ਜਮ ਰੂਪ ਨਿਹਾਰਿਯੋ।","roman":"Aavat hee jadubeer tino ran bhoomi bikhai jam roop nihaariyo |","meaning_en":"","page":519},{"gurmukhi":"ਪਾਨਿ ਗਹੇ ਧਨੁ ਬਾਨ ਸੋਊ ਰਨ ਬੀਚ ਤਿਨੋ ਬਲਿਦੇਵ ਹਕਾਰਿਯੋ।","roman":"Paani gahe dhanu baan so'oo ran beech tino balidev hakaariyo |","meaning_en":"","page":519},{"gurmukhi":"ਖਗ ਕਸੇ ਕਟਿ ਮੈ ਅੰਗ ਕੌਚ ਲੀਏ ਬਰਛਾ ਅਣਗੇਸ ਪੁਕਾਰਿਯੋ।","roman":"Khag kase kati mai ang kauch lee'e barchhaa anges pukaariyo |","meaning_en":"","page":519},{"gurmukhi":"ਆਇ ਭਿਰੋ ਹਰਿ ਜੂ ਹਮ ਸਿਉ ਅਬ ਠਾਢੋ ਕਹਾ ਇਹ ਭਾਤ ਉਚਾਰਿਯੋ। ੧੧੩੮।","roman":"Aai bhiro hari joo ham siu ab thaadho kahaa ih bhaat uchaariyo | 1138 |","meaning_en":"","page":519}]},{"type":"verse","number":[1139],"number_text":"੧੧੩੯।","page":519,"lines":[{"gurmukhi":"ਦੇਖਿ ਤਬੈ ਤਿਨ ਕੋ ਹਰਿ ਜੂ ਤਬ ਹੀ ਰਨ ਮੈ ਪੰਚ ਬੀਰ ਹਕਾਰੇ।","roman":"Dekhi tabai tin ko hari joo tab hee ran mai panch beer hakaare |","meaning_en":"","page":519},{"gurmukhi":"ਸ੍ਯਾਮ ਸੁ ਸੈਨ ਚਲਿਯੋ ਇਤ ਤੇ ਉਤ ਤੇਊ ਚਲੇ ਸੁ ਬਜਾਇ ਨਗਾਰੇ।","roman":"Syaam su sain chaliyo it te ut teoo chale su bajaai nagaare |","meaning_en":"","page":519},{"gurmukhi":"ਪਟਸਿ ਲੋਹ ਹਥੀ ਪਰਸੇ ਅਗਨਾਯੁਧ ਲੈ ਕਰਿ ਕੋਪ ਪ੍ਰਹਾਰੇ।","roman":"Patsi loh hathee parse agnaayudh lai kari kop prahaare |","meaning_en":"","page":519},{"gurmukhi":"ਜੂਝਿ ਗਿਰੇ ਇਤ ਕੇ ਉਤ ਕੇ ਭਟ ਭੂਮਿ ਗਿਰੇ ਸੁ ਮਨੋ ਮਤਵਾਰੇ। ੧੧੩੯।","roman":"Joojhi gire it ke ut ke bhat bhoomi gire su mano matvaare | 1139 |","meaning_en":"","page":519}]},{"type":"verse","number":[1140],"number_text":"੧੧੪੦।","page":519,"lines":[{"gurmukhi":"ਜੁਧ ਭਯੋ ਤਿਹ ਠਉਰ ਬਡੋ ਚਢਿ ਕੈ ਸਭ ਦੇਵ ਬਿਵਾਨਨਿ ਆਏ।","roman":"Judh bhayo tih thaur bado chadhi kai sabh dev bivaanni aae |","meaning_en":"","page":519},{"gurmukhi":"ਕਉਤਕ ਦੇਖਨ ਕਉ ਰਨ ਕੋ ਕਬਿ ਸ੍ਯਾਮ ਕਹੈ ਮਨ ਮੋਦ ਬਢਾਏ।","roman":"Kautak dekhan kau ran ko kabi syaam kahai man mod badhaae |","meaning_en":"","page":519},{"gurmukhi":"ਲਾਗਤ ਸਾਂਗਨ ਕੇ ਭਟ ਯੌ ਗਿਰ ਅਸਵਨ ਤੇ ਧਰਨੀ ਪਰ ਆਏ।","roman":"Laagat saangan ke bhat yau gir asvan te dharnee par aae |","meaning_en":"","page":519},{"gurmukhi":"ਸੋ ਫਿਰ ਕੈ ਉਠਿ ਜੁਧ ਕਰੈ ਤਿਹ ਕੇ ਗੁਨ ਕਿੰਨ ਗੰਧ੍ਰਬ ਗਾਏ। ੧੧੪੦।","roman":"So phir kai uthi judh karai tih ke gun kinn gandhrab gaae | 1140 |","meaning_en":"","page":519}]},{"type":"heading","kind":"chhand","name":"ਕਬਿਤੁ","gurmukhi":"ਕਬਿਤੁ","roman":"Kabitu","meaning_en":"","page":519},{"type":"verse","number":[1141],"number_text":"੧੧੪੧।","page":519,"lines":[{"gurmukhi":"ਕੇਤੇ ਬੀਰ ਭਾਜੇ ਕੇਤੇ ਗਾਜੇ ਪੁਨਿ ਆਇ ਆਇ","roman":"Kete beer bhaaje kete gaaje puni aai aai","meaning_en":"","page":519},{"gurmukhi":"ਧਾਇ ਧਾਇ ਹਰਿ ਜੂ ਸੋ ਜੁਧ ਵੇ ਕਰਤ ਹੈ।","roman":"Dhaai dhaai hari joo so judh ve karat hai |","meaning_en":"","page":519},{"gurmukhi":"ਕੇਤੇ ਭੂਮਿ ਗਿਰੇ ਕੇਤੇ ਭਿਰੇ ਗਜ ਮਤਨ ਸੋ","roman":"Kete bhoomi gire kete bhire gaj matan so","meaning_en":"","page":520},{"gurmukhi":"ਲਰੇ ਤੇਤੋ ਮ੍ਰਿਤਕ ਹ੍ਵੈ ਕੈ ਛਿਤਿ ਮੈ ਪਰਤ ਹੈ।","roman":"Lare teto mritak hvai kai chhiti mai parat hai |","meaning_en":"","page":520,"flags":[{"code":"ੋੋ","reason":"same sign typed twice; written once (prints as one)"}]},{"gurmukhi":"ਅਉਰ ਦਉਰ ਪਰੇ ਮਾਰ ਮਾਰ ਹੀ ਉਚਰੇ","roman":"Aur daur pare maar maar hee uchre","meaning_en":"","page":520},{"gurmukhi":"ਹਥਿਯਾਰਨ ਉਘਰੇ ਪਗੁ ਏਕ ਨ ਟਰਤ ਹੈ।","roman":"Hathiyaaran ughre pagu ek na tarat hai |","meaning_en":"","page":520},{"gurmukhi":"ਸ੍ਰਉਣਤ ਉਦਧਿ ਲੋਹ ਆਚ ਬੜਵਾਨਲ ਸੀ","roman":"Sraunat uddhi loh aach barvaanal see","meaning_en":"","page":520},{"gurmukhi":"ਪਉਨ ਬਾਨ ਚਲੈ ਬੀਰ ਤ੍ਰਿਣ ਜਿਉ ਜਰਤ ਹੈ। ੧੧੪੧।","roman":"Paun baan chalai beer trin jiu jarat hai | 1141 |","meaning_en":"","page":520}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":520},{"type":"verse","number":[1142],"number_text":"੧੧੪੨।","page":520,"lines":[{"gurmukhi":"ਅਣਗੇਸ ਬਲੀ ਤਬ ਕੋਪਿ ਭਰਿਯੋ ਮਨਿ ਜਾਨ ਨਿਦਾਨ ਕੀ ਮਾਰ ਮਚੀ ਜਬ।","roman":"Anges balee tab kopi bhariyo mani jaan nidaan kee maar machee jab |","meaning_en":"","page":520},{"gurmukhi":"ਸ੍ਯੰਦਨ ਪੈ ਚਢਿ ਕੈ ਕਢਿ ਕੈ ਕਸਿ ਬਾਨ ਕਮਾਨ ਤਨਾਇ ਲਈ ਤਬ।","roman":"Syandan pai chadhi kai kadhi kai kasi baan kamaan tanaai laee tab |","meaning_en":"","page":520},{"gurmukhi":"ਸ੍ਰੀ ਹਰਿ ਕੀ ਪ੍ਰਿਤਨਾ ਹੂ ਕੇ ਊਪਰਿ ਆਇ ਪਰਿਯੋ ਤਿਨ ਬੀਰ ਹਨੇ ਸਬ।","roman":"Sree hari kee pritnaa hoo ke oopri aai pariyo tin beer hane sab |","meaning_en":"","page":520},{"gurmukhi":"ਭਾਜਿ ਗਏ ਤਮ ਸੇ ਅਰਿ ਯੌ ਨ੍ਰਿਪ ਪਾਵਤ ਭਯੋ ਰਨਿ ਸੂਰਜ ਕੀ ਛਬਿ। ੧੧੪੨।","roman":"Bhaaji gae tam se ari yau nrip paavat bhayo rani sooraj kee chhabi | 1142 |","meaning_en":"","page":520}]},{"type":"verse","number":[1143],"number_text":"੧੧੪੩।","page":520,"lines":[{"gurmukhi":"ਪ੍ਰੇਰਿ ਤੁਰੰਗ ਸੁ ਆਗੇ ਭਯੋ ਕਰਿ ਲੈ ਅਸਿ ਢਾਰ ਬਡੀ ਧਰ ਕੈ।","roman":"Preri turang su aage bhayo kari lai asi dhaar badee dhar kai |","meaning_en":"","page":520},{"gurmukhi":"ਕਛੁ ਜਾਦਵ ਸੋ ਤਿਨਿ ਜੁਧੁ ਕਰਿਯੋ ਨ ਟਰਿਯੋ ਤਿਨ ਸੋ ਪਗ ਦੁਇ ਡਰ ਕੈ।","roman":"Kachhu jaadav so tini judhu kariyo na tariyo tin so pag dui dar kai |","meaning_en":"","page":520},{"gurmukhi":"ਜਦੁਬੀਰ ਕੇ ਸਾਮੁਹੇ ਆਇ ਅਰਿਯੋ ਬਹੁ ਬੀਰਨ ਪ੍ਰਾਨ ਬਿਦਾ ਕਰਿ ਕੈ।","roman":"Jadubeer ke saamuhe aai ariyo bahu beeran praan bidaa kari kai |","meaning_en":"","page":520},{"gurmukhi":"ਗ੍ਰਿਹੁ ਕੋ ਨ ਚਲੋ ਇਹ ਮੋ ਪ੍ਰਨ ਹੈ ਕਿਧੋ ਪ੍ਰਾਨ ਤਜਉ ਕਿ ਤ੍ਵੈ ਮਰਿ ਕੈ। ੧੧੪੩।","roman":"Grihu ko na chalo ih mo pran hai kidho praan tajau ki tvai mari kai | 1143 |","meaning_en":"","page":520}]},{"type":"verse","number":[1144],"number_text":"੧੧੪੪।","page":520,"lines":[{"gurmukhi":"ਯੌ ਕਹਿ ਕੈ ਅਸਿ ਕੋ ਗਹਿ ਕੈ ਜਦੁਬੀਰ ਚਮੂ ਕਹੁ ਜਾਇ ਹਕਾਰਾ।","roman":"Yau kahi kai asi ko gahi kai jadubeer chamoo kahu jaai hakaaraa |","meaning_en":"","page":520,"flags":[{"code":"ੁ+ੂ","reason":"overlapping ੁ and ੂ drawn as one ੂ"}]},{"gurmukhi":"ਜਾਦਵ ਸੈਨ ਹੂੰ ਤੇ ਨਿਕਸਿਯੋ ਰਨ ਸੁੰਦਰ ਨਾਮ ਸਰੂਪ ਅਪਾਰਾ।","roman":"Jaadav sain hoon te niksiyo ran sundar naam saroop apaaraa |","meaning_en":"","page":520},{"gurmukhi":"ਪ੍ਰੇਰਿ ਤੁਰੰਗ ਭਯੋ ਸਮੁਹੇ ਨ੍ਰਿਪ ਮੁੰਡ ਕਟਿਯੋ ਨ ਲਗੀ ਕਛੁ ਬਾਰਾ।","roman":"Preri turang bhayo samuhe nrip mund katiyo na lagee kachhu baaraa |","meaning_en":"","page":520},{"gurmukhi":"ਯੌ ਧਰ ਤੇ ਸਿਰ ਛੂਟ ਪਰਿਯੋ ਨਭਿ ਤੇ ਟੂਟ ਪਰੋ ਛਿਤ ਤਾਰਾ। ੧੧੪੪।।","roman":"Yau dhar te sir chhoot pariyo nabhi te toot paro chhit taaraa | 1144 ||","meaning_en":"","page":520}]},{"type":"verse","number":[1145],"number_text":"੧੧੪੫।","page":520,"lines":[{"gurmukhi":"ਪੁਨਿ ਦਉਰਿ ਪਰਿਯੋ ਜਦੁਵੀ ਪ੍ਰਿਤਨਾ ਪਰ ਸ੍ਯਾਮ ਕਹੈ ਅਤਿ ਕੀਨ ਰੁਸਾ।","roman":"Puni dauri pariyo jaduvee pritnaa par syaam kahai ati keen rusaa |","meaning_en":"","page":520},{"gurmukhi":"ਉਤ ਤੇ ਜਦੁਬੀਰ ਫਿਰੇ ਇਕਠੇ ਅਰਿਰਾਇ ਬਢਾਇ ਕੈ ਚਿਤ ਗੁਸਾ।","roman":"Ut te jadubeer phire ikthe ariraai badhaai kai chit gusaa |","meaning_en":"","page":520},{"gurmukhi":"ਅਗਨਸਤ੍ਰ ਛੁਟਿਯੋ ਨ੍ਰਿਪ ਕੇ ਕਰ ਤੇ ਜਰਗੇ ਮਨੋ ਪਾਵਕ ਬੀਚ ਤੁਸਾ।","roman":"Agansatr chhutiyo nrip ke kar te jarge mano paavak beech tusaa |","meaning_en":"","page":520},{"gurmukhi":"ਕਟਿ ਅੰਗ ਪਰੇ ਬਹੁ ਜੋਧਨ ਕੇ ਮਨੋ ਜਗ ਕੇ ਮੰਡਲ ਮਧਿ ਕੁਸਾ। ੧੧੪੫।","roman":"Kati ang pare bahu jodhan ke mano jag ke mandal madhi kusaa | 1145 |","meaning_en":"","page":520}]},{"type":"verse","number":[1146],"number_text":"੧੧੪੬।","page":520,"lines":[{"gurmukhi":"ਕਾਨ ਪ੍ਰਮਾਨ ਲਉ ਖੈਚ ਕਮਾਨ ਸੁ ਬੀਰ ਨਿਹਾਰ ਕੈ ਬਾਨ ਚਲਾਵੈ।","roman":"Kaan pramaan lau khaich kamaan su beer nihaar kai baan chalaavai |","meaning_en":"","page":520},{"gurmukhi":"ਜੋ ਇਨਿ ਊਪਰਿ ਆਨ ਪਰੇ ਸਰ ਸੋ ਅਧ ਬੀਚ ਤੇ ਕਾਟਿ ਗਿਰਾਵੈ।","roman":"Jo ini oopri aan pare sar so adh beech te kaati giraavai |","meaning_en":"","page":520},{"gurmukhi":"ਲੋਹ ਹਥੀ ਪਰਸੇ ਕਰਿ ਲੈ ਬ੍ਰਿਜਨਾਥ ਕੀ ਦੇਹਿ ਪ੍ਰਹਾਰ ਲਗਾਵੈ।","roman":"Loh hathee parse kari lai brijnaath kee dehi prahaar lagaavai |","meaning_en":"","page":520},{"gurmukhi":"ਜੁਧ ਸਮੈ ਥਕਿ ਕੈ ਜਕਿ ਕੈ ਜਦੁਬੀਰ ਕਉ ਪਾਰ ਸੰਭਾਰ ਨ ਆਵੈ। ੧੧੪੬।","roman":"Judh samai thaki kai jaki kai jadubeer kau paar sanbhaar na aavai | 1146 |","meaning_en":"","page":520}]},{"type":"verse","number":[1147],"number_text":"੧੧੪੭।","page":521,"lines":[{"gurmukhi":"ਜੋ ਇਹ ਉਪਰ ਆਇ ਪਰੇ ਭਟ ਕੋਪ ਭਰੇ ਇਨ ਹੂੰ ਸੁ ਨਿਵਾਰੇ।","roman":"Jo ih upar aai pare bhat kop bhare in hoon su nivaare |","meaning_en":"","page":521},{"gurmukhi":"ਬਾਨ ਕਮਾਨ ਕ੍ਰਿਪਾਨ ਗਦਾ ਗਹਿ ਮਾਰਿ ਰਥੀ ਬਿਰਥੀ ਕਰਿ ਡਾਰੇ।","roman":"Baan kamaan kripaan gadaa gahi maari rathee birthee kari daare |","meaning_en":"","page":521},{"gurmukhi":"ਘਾਇਲ ਕੋਟਿ ਚਲੇ ਤਜਿ ਕੈ ਰਨ ਜੂਝਿ ਪਰੇ ਬਹੁ ਡੀਲ ਡਰਾਰੇ।","roman":"Ghaail koti chale taji kai ran joojhi pare bahu deel daraare |","meaning_en":"","page":521},{"gurmukhi":"ਯੌ ਉਪਜੀ ਉਪਮਾ ਸੁ ਮਨੋ ਅਹਿਰਾਜ ਪਰੇ ਖਗਰਾਜ ਕੇ ਮਾਰੇ। ੧੧੪੭।","roman":"Yau upjee upmaa su mano ahiraaj pare khagraaj ke maare | 1147 |","meaning_en":"","page":521}]},{"type":"verse","number":[1148],"number_text":"੧੧੪੮।","page":521,"lines":[{"gurmukhi":"ਜੁਧ ਕੀਯੋ ਜਦੁਬੀਰਨ ਸੋ ਉਹ ਬੀਰ ਜਬੈ ਕਰ ਮੈ ਅਸਿ ਸਾਜਿਯੋ।","roman":"Judh keeyo jadubeeran so uh beer jabai kar mai asi saajiyo |","meaning_en":"","page":521},{"gurmukhi":"ਮਾਰਿ ਚਮੂੰ ਸੁ ਬਿਦਾਰ ਦਈ ਕਬਿ ਰਾਮ ਕਹੈ ਬਲੁ ਸੋ ਨ੍ਰਿਪ ਗਾਜਿਯੋ।","roman":"Maari chamoon su bidaar daee kabi raam kahai balu so nrip gaajiyo |","meaning_en":"","page":521},{"gurmukhi":"ਸੋ ਸੁਨਿ ਬੀਰ ਡਰੇ ਸਬਹੀ ਧੁਨਿ ਕਉ ਸੁਨ ਕੈ ਘਨ ਸਾਵਨ ਲਾਜਿਯੋ।","roman":"So suni beer dare sabhee dhuni kau sun kai ghan saavan laajiyo |","meaning_en":"","page":521},{"gurmukhi":"ਛਾਜਤ ਯੌ ਅਰਿ ਕੇ ਗਨ ਮੈ ਮ੍ਰਿਗ ਕੇ ਬਨ ਮਨੋ ਸਿੰਘ ਬਿਰਾਜਿਯੋ। ੧੧੪੮।","roman":"Chhaajat yau ari ke gan mai mrig ke ban mano singh biraajiyo | 1148 |","meaning_en":"","page":521}]},{"type":"verse","number":[1149],"number_text":"੧੧੪੯।","page":521,"lines":[{"gurmukhi":"ਬਹੁਰ ਕਰਵਾਰ ਸੰਭਾਰਿ ਬਿਦਾਰਿ ਦਈ ਧੁਜਨੀ ਨ੍ਰਿਪ ਕੋਟਿ ਮਰੇ।","roman":"Bahur karvaar sanbhaari bidaari daee dhujnee nrip koti mare |","meaning_en":"","page":521},{"gurmukhi":"ਅਸਵਾਰ ਹਜਾਰ ਪਚਾਸ ਹਨੇ ਰਥ ਕਾਟਿ ਰਥੀ ਬਿਰਥੀ ਸੁ ਕਰੇ।","roman":"Asvaar hajaar pachaas hane rath kaati rathee birthee su kare |","meaning_en":"","page":521},{"gurmukhi":"ਕਹੂੰ ਬਾਜ ਗਿਰੈ ਕਹੂੰ ਤਾਜ ਜਿਰੇ ਗਜਰਾਰ ਘਿਰੇ ਕਹੂੰ ਰਾਜ ਪਰੇ।","roman":"Kahoon baaj girai kahoon taaj jire gajraar ghire kahoon raaj pare |","meaning_en":"","page":521},{"gurmukhi":"ਥਿਰੁ ਨਾਹਿ ਰਹੈ ਨ੍ਰਿਪ ਕੋ ਰਥ ਭੂਮਿ ਮਨੋ ਨਟੂਆ ਬਹੁ ਨ੍ਰਿਤ ਕਰੇ। ੧੧੪੯।","roman":"Thiru naahi rahai nrip ko rath bhoomi mano natooaa bahu nrit kare | 1149 |","meaning_en":"","page":521}]},{"type":"verse","number":[1150],"number_text":"੧੧੫੦।","page":521,"lines":[{"gurmukhi":"ਏਕ ਅਜਾਇਬ ਖਾਂ ਹਰਿ ਕੋ ਭਟ ਤਾ ਸੰਗ ਸੋ ਨ੍ਰਿਪ ਆਨ ਅਰਿਯੋ ਹੈ।","roman":"Ek ajaaib khaan hari ko bhat taa sang so nrip aan ariyo hai |","meaning_en":"","page":521},{"gurmukhi":"ਭਾਜਤ ਨਾਹਿ ਹਠੀ ਰਨ ਤੇ ਅਣਗੇਸ ਬਲੀ ਅਤਿ ਕੋਪ ਭਰਿਯੋ ਹੈ।","roman":"Bhaajat naahi hathee ran te anges balee ati kop bhariyo hai |","meaning_en":"","page":521},{"gurmukhi":"ਲੈ ਕਰਵਾਰ ਪ੍ਰਹਾਰ ਕੀਯੋ ਕਟਿਯੋ ਤਿਹ ਸੀਸ ਕਬੰਧ ਲਰਿਯੋ ਹੈ।","roman":"Lai karvaar prahaar keeyo katiyo tih sees kabandh lariyo hai |","meaning_en":"","page":521},{"gurmukhi":"ਫੇਰਿ ਗਿਰਿਯੋ ਮਾਨੋ ਆਧੀ ਬਹੀ ਦ੍ਰੁਮ ਦੀਰਘ ਭੂ ਪਰਿ ਟੂਟ ਪਰਿਯੋ ਹੈ। ੧੧੫੦।","roman":"Pheri giriyo maano aadhee bahee drum deeragh bhoo pari toot pariyo hai | 1150 |","meaning_en":"","page":521,"flags":[{"code":"0x71","reason":"subjoined letter typed after the vowel/nasal sign; put in Unicode order (same printed shape)"}]}]},{"type":"verse","number":[1151],"number_text":"੧੧੫੧।","page":521,"lines":[{"gurmukhi":"ਦੇਖਿ ਅਜਾਇਬ ਖਾਨ ਦਸਾ ਤਬ ਗੈਰ ਖਾਂ ਮਨਿ ਰੋਸ ਭਰਿਯੋ।","roman":"Dekhi ajaaib khaan dasaa tab gair khaan mani ros bhariyo |","meaning_en":"","page":521},{"gurmukhi":"ਸੁ ਧਵਾਇ ਕੈ ਸ੍ਯੰਦਨ ਜਾਇ ਪਰਿਯੋ ਅਰਿ ਬੀਰ ਹੂੰ ਤੇ ਨਹੀ ਨੈਕੁ ਡਰਿਯੋ।","roman":"Su dhavaai kai syandan jaai pariyo ari beer hoon te nahee naiku dariyo |","meaning_en":"","page":521},{"gurmukhi":"ਅਸਿ ਪਾਨਿ ਧਰੇ ਰਨ ਬੀਚ ਦੁਹੂੰ ਤਹ ਆਪਸ ਮੈ ਬਹੁ ਜੁਧ ਕਰਿਯੋ।","roman":"Asi paani dhare ran beech duhoon tah aapas mai bahu judh kariyo |","meaning_en":"","page":521},{"gurmukhi":"ਮਨਿ ਯੌ ਉਪਜੀ ਉਪਮਾ ਬਨ ਮੈ ਗਜ ਸੋ ਮਦ ਕੋ ਗਜ ਆਨਿ ਅਰਿਯੋ। ੧੧੫੧।","roman":"Mani yau upjee upmaa ban mai gaj so mad ko gaj aani ariyo | 1151 |","meaning_en":"","page":521}]},{"type":"verse","number":[1152],"number_text":"੧੧੫੨।","page":521,"lines":[{"gurmukhi":"ਗੈਰਤ ਖਾਂ ਬਰਛੀ ਗਹਿ ਕੈ ਬਰ ਸੋ ਅਰਿ ਬੀਰ ਕੀ ਓਰਿ ਚਲਾਈ।","roman":"Gairat khaan barchhee gahi kai bar so ari beer kee ori chalaaee |","meaning_en":"","page":521},{"gurmukhi":"ਆਵਤ ਬਿਦੁਲਤਾ ਸਮ ਦੇਖ ਕੈ ਕਾਟਿ ਕ੍ਰਿਪਾਨ ਸੋ ਭੂਮਿ ਗਿਰਾਈ।","roman":"Aavat bidultaa sam dekh kai kaati kripaan so bhoomi giraaee |","meaning_en":"","page":521},{"gurmukhi":"ਸੋ ਨ ਲਗੀ ਰਿਸ ਕੈ ਰਿਪੁ ਕੋ ਬਰਛੀ ਗਹਿ ਦੂਸਰੀ ਅਉਰ ਚਲਾਈ।","roman":"So na lagee ris kai ripu ko barchhee gahi doosree aur chalaaee |","meaning_en":"","page":521},{"gurmukhi":"ਯੌ ਉਪਮਾ ਉਪਜੀ ਜੀਯ ਮੈ ਮਾਨੋ ਛੂਟਿ ਚਲੀ ਨਭ ਤੇ ਜੁ ਹਵਾਈ। ੧੧੫੨।","roman":"Yau upmaa upjee jeey mai maano chhooti chalee nabh te ju havaaee | 1152 |","meaning_en":"","page":521}]},{"type":"verse","number":[1153],"number_text":"੧੧੫੩।","page":521,"lines":[{"gurmukhi":"ਦੂਸਰੀ ਦੇਖ ਕੈ ਸਾਂਗ ਬਲੀ ਨ੍ਰਿਪ ਆਵਤ ਕਾਟਿ ਕੈ ਭੂਮਿ ਗਿਰਾਈ।","roman":"Doosree dekh kai saang balee nrip aavat kaati kai bhoomi giraaee |","meaning_en":"","page":521},{"gurmukhi":"ਲੈ ਬਰਛੀ ਅਪੁਨੇ ਕਰ ਮੈ ਨ੍ਰਿਪ ਗੈਰਤ ਖਾਂ ਪਰ ਕੋਪਿ ਚਲਾਈ।","roman":"Lai barchhee apune kar mai nrip gairat khaan par kopi chalaaee |","meaning_en":"","page":521},{"gurmukhi":"ਲਾਗ ਗਈ ਤਿਹ ਕੇ ਮੁਖ ਮੈ ਬਹਿ ਸ੍ਰਉਨ ਚਲਿਯੋ ਉਪਮਾ ਠਹਰਾਈ।","roman":"Laag gaee tih ke mukh mai bahi sraun chaliyo upmaa thahraaee |","meaning_en":"","page":522},{"gurmukhi":"ਕੋਪ ਕੀ ਆਗ ਮਹਾ ਬਢਿ ਕੈ ਡਢ ਕੈ ਹੀਯ ਕਉ ਮਨੋ ਬਾਹਰਿ ਆਈ। ੧੧੫੩।","roman":"Kop kee aag mahaa badhi kai dadh kai heey kau mano baahri aaee | 1153 |","meaning_en":"","page":522}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":522},{"type":"verse","number":[1154],"number_text":"੧੧੫੪।","page":522,"lines":[{"gurmukhi":"ਮ੍ਰਿਤਕ ਹੁਇ ਧਰਨੀ ਪਰਿਯੋ ਜੋਤਿ ਰਹੀ ਠਹਰਾਇ।","roman":"Mritak hui dharnee pariyo joti rahee thahraai |","meaning_en":"","page":522},{"gurmukhi":"ਜਨੁ ਅਕਾਸ ਤੇ ਭਾਸਕਰਿ ਪਯੋ ਰਾਹੁ ਡਰ ਆਇ। ੧੧੫੪।","roman":"Janu akaas te bhaasakri payo raahu dar aai | 1154 |","meaning_en":"","page":522}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":522},{"type":"verse","number":[1155],"number_text":"੧੧੫੫।","page":522,"lines":[{"gurmukhi":"ਕੋਪ ਭਰੇ ਰਨ ਮੈ ਕਬਿ ਸ੍ਯਾਮ ਤਬੈ ਹਰਿ ਜੂ ਇਹ ਭਾਤਿ ਕਹਿਯੋ ਹੈ।","roman":"Kop bhare ran mai kabi syaam tabai hari joo ih bhaati kahiyo hai |","meaning_en":"","page":522},{"gurmukhi":"ਜੁਧ ਬਿਖੈ ਭਟ ਕਉਨ ਗਨੈ ਲਖਿ ਬੀਰ ਹਨੈ ਮਨ ਮੈ ਜੁ ਚਹਿਯੋ ਹੈ।","roman":"Judh bikhai bhat kaun ganai lakhi beer hanai man mai ju chahiyo hai |","meaning_en":"","page":522},{"gurmukhi":"ਜਾਨਤ ਹਉ ਤਿਹ ਤ੍ਰਾਸ ਤੁਮੈ ਕਿਨ ਹੂੰ ਕਰ ਮੈ ਧਨ ਹੂੰ ਗਹਿਯੋ ਹੈ।","roman":"Jaanat hau tih traas tumai kin hoon kar mai dhan hoon gahiyo hai |","meaning_en":"","page":522},{"gurmukhi":"ਤਾਤੇ ਪਧਾਰਹੁ ਧਾਮਨ ਕੋ ਸੁ ਲਖਿਯੋ ਤੁਮ ਤੇ ਪੁਰਖਤੁ ਰਹਿਯੋ ਹੈ। ੧੧੫੫।","roman":"Taate padhaarhu dhaaman ko su lakhiyo tum te purakhtu rahiyo hai | 1155 |","meaning_en":"","page":522}]},{"type":"verse","number":[1156],"number_text":"੧੧੫੬।","page":522,"lines":[{"gurmukhi":"ਐਸੇ ਕਹਿਯੋ ਜਦੁਬੀਰ ਤਿਨੈ ਸਭ ਹੀ ਰਿਸ ਕੈ ਧਨੁ ਬਾਨ ਸੰਭਾਰਿਯੋ।","roman":"Aise kahiyo jadubeer tinai sabh hee ris kai dhanu baan sanbhaariyo |","meaning_en":"","page":522},{"gurmukhi":"ਹ੍ਵੈ ਕੇ ਇਕਤ੍ਰ ਚਲੇ ਰਲ ਕੋ ਬਲਿ ਬਿਕ੍ਰਮ ਪਉਰਖ ਜੀਅ ਬਿਚਾਰਿਯੋ।","roman":"Hvai ke ikatr chale ral ko bali bikram paurakh jeea bichaariyo |","meaning_en":"","page":522},{"gurmukhi":"ਮਾਰ ਹੀ ਮਾਰ ਪੁਕਾਰਿ ਪਰੇ ਜੋਊ ਆਇ ਅਰਿਯੋ ਅਰਿ ਸੋ ਤਿਹ ਮਾਰਿਯੋ।","roman":"Maar hee maar pukaari pare jo'oo aai ariyo ari so tih maariyo |","meaning_en":"","page":522},{"gurmukhi":"ਹੋਤ ਭਯੋ ਤਿਹ ਜੁਧ ਬਡੋ ਦੁਹੂੰ ਓਰਨ ਤੇ ਨ੍ਰਿਪ ਠਾਢਿ ਨਿਹਾਰਿਯੋ। ੧੧੫੬।","roman":"Hot bhayo tih judh bado duhoon oran te nrip thaadhi nihaariyo | 1156 |","meaning_en":"","page":522}]},{"type":"verse","number":[1157],"number_text":"੧੧੫੭।","page":522,"lines":[{"gurmukhi":"ਏਕ ਸੁਜਾਨ ਬਡੋ ਬਲਵਾਨ ਧਰੇ ਅਸਿ ਪਾਨਿ ਤੁਰੰਗਮ ਡਾਰਿਯੋ।","roman":"Ek sujaan bado balvaan dhare asi paani turangam daariyo |","meaning_en":"","page":522},{"gurmukhi":"ਅਸ੍ਵ ਪਚਾਸ ਹਨੇ ਅਰਿ ਯੌ ਅਨਗੇਸ ਬਲੀ ਕਹੁ ਜਾ ਲਲਕਾਰਿਯੋ।","roman":"Asv pachaas hane ari yau anges balee kahu jaa lalkaariyo |","meaning_en":"","page":522},{"gurmukhi":"ਧਾਇ ਕੈ ਘਾਇ ਕਰਿਯੋ ਨ੍ਰਿਪ ਲੈ ਕਰ ਬਾਮ ਮੈ ਚਾਮ ਕੀ ਓਟਿ ਨਿਵਾਰਿਯੋ।","roman":"Dhaai kai ghaai kariyo nrip lai kar baam mai chaam kee oti nivaariyo |","meaning_en":"","page":522},{"gurmukhi":"ਦਾਹਨੈ ਪਾਨਿ ਕ੍ਰਿਪਾਨ ਕੋ ਤਾਨਿ ਸੁਜਾਨ ਕੋ ਕਾਟਿ ਕੈ ਸੀਸ ਉਤਾਰਿਯੋ। ੧੧੫੭।","roman":"Daahnai paani kripaan ko taani sujaan ko kaati kai sees utaariyo | 1157 |","meaning_en":"","page":522}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":522},{"type":"verse","number":[1158],"number_text":"੧੧੫੮।","page":522,"lines":[{"gurmukhi":"ਬੀਰ ਸੁਜਾਨ ਹਨ੍ਯੋ ਜਬੈ ਅਣਗ ਸਿੰਘ ਤਿਹ ਠਾਇ।","roman":"Beer sujaan hanyo jabai anag singh tih thaai |","meaning_en":"","page":522},{"gurmukhi":"ਦੇਖਿਯੋ ਸੈਨਾ ਜਾਦਵੀ ਦਉਰ ਪਰੇ ਅਰਰਾਇ। ੧੧੫੮।","roman":"Dekhiyo sainaa jaadvee daur pare arraai | 1158 |","meaning_en":"","page":522}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":522},{"type":"verse","number":[1159],"number_text":"੧੧੫੯।","page":522,"lines":[{"gurmukhi":"ਭਟ ਲਾਜ ਭਰੇ ਅਰਰਾਇ ਪਰੇ ਨ ਡਰੇ ਅਰਿ ਸਿਉ ਤੇਊ ਆਇ ਅਰੇ।","roman":"Bhat laaj bhare arraai pare na dare ari siu teoo aai are |","meaning_en":"","page":522},{"gurmukhi":"ਅਤਿ ਕੋਪ ਭਰੇ ਸਬ ਲੋਹ ਜਰੇ ਅਬ ਯਾਹਿ ਹਨੋ ਮੁਖ ਤੇ ਉਚਰੇ।","roman":"Ati kop bhare sab loh jare ab yaahi hano mukh te uchre |","meaning_en":"","page":522},{"gurmukhi":"ਅਸਿ ਭਾਲ ਗਦਾ ਅਰੁ ਲੋਹ ਹਥੀ ਬਰਛੀ ਕਰਿ ਲੈ ਲਲਕਾਰ ਪਰੇ।","roman":"Asi bhaal gadaa aru loh hathee barchhee kari lai lalkaar pare |","meaning_en":"","page":522},{"gurmukhi":"ਕਬਿ ਰਾਮ ਭਨੈ ਨਹੀ ਜਾਤ ਗਨੇ ਕਿਤਨੇ ਬਰ ਬਾਨ ਕਮਾਨ ਧਰੇ। ੧੧੫੯।","roman":"Kabi raam bhanai nahee jaat gane kitne bar baan kamaan dhare | 1159 |","meaning_en":"","page":522}]},{"type":"verse","number":[1160],"number_text":"੧੧੬੦।","page":523,"lines":[{"gurmukhi":"ਅਨਗੇਸ ਬਲੀ ਧਨੁ ਬਾਨ ਗਹਿਯੋ ਅਤਿ ਰੋਸ ਭਰਿਯੋ ਦੋਊ ਨੈਨ ਤਚਾਏ।","roman":"Anges balee dhanu baan gahiyo ati ros bhariyo do'oo nain tachaae |","meaning_en":"","page":523},{"gurmukhi":"ਮਾਰ ਹੀ ਮਾਰ ਪੁਕਾਰਿ ਪਰਿਯੋ ਸਰ ਸਤ੍ਰਨ ਕੇ ਉਰ ਬੀਚ ਲਗਾਏ।","roman":"Maar hee maar pukaari pariyo sar satran ke ur beech lagaae |","meaning_en":"","page":523},{"gurmukhi":"ਏਕ ਮਰੇ ਇਕ ਘਾਇ ਭਰੇ ਇਕ ਦੇਖਿ ਡਰੇ ਰਨ ਤਿਆਗਿ ਪਰਾਏ।","roman":"Ek mare ik ghaai bhare ik dekhi dare ran tiaagi paraae |","meaning_en":"","page":523},{"gurmukhi":"ਆਇ ਲਰੇ ਜੋਊ ਲਾਜ ਭਰੇ ਮਨ ਮੈ ਰਨ ਕੋਪ ਕੀ ਓਪ ਬਢਾਏ। ੧੧੬੦।","roman":"Aai lare jo'oo laaj bhare man mai ran kop kee op badhaae | 1160 |","meaning_en":"","page":523}]},{"type":"verse","number":[1161],"number_text":"੧੧੬੧।","page":523,"lines":[{"gurmukhi":"ਸਾਤਕਿ ਅਉ ਮੁਸਲੀ ਰਥ ਪੈ ਬਸੁਦੇਵ ਤੇ ਆਦਿਕ ਧਾਇ ਸਬੈ।","roman":"Saatki au muslee rath pai basudev te aadik dhaai sabai |","meaning_en":"","page":523},{"gurmukhi":"ਬਰਮਾਕ੍ਰਿਤ ਊਧਵ ਅਉਰ ਅਕ੍ਰੂਰ ਚਲੇ ਰਨ ਕਉ ਭਰਿ ਲਾਜ ਤਬੈ।","roman":"Barmaakrit oodhav aur akroor chale ran kau bhari laaj tabai |","meaning_en":"","page":523},{"gurmukhi":"ਤਿਹ ਬੀਚ ਘਿਰਿਓ ਨ੍ਰਿਪ ਰਾਜਤ ਯੌ ਲਖਿ ਰੀਝ ਰਹੈ ਭਟ ਤਾਹਿ ਛਬੈ।","roman":"Tih beech ghirio nrip raajat yau lakhi reejh rahai bhat taahi chhabai |","meaning_en":"","page":523},{"gurmukhi":"ਮਨ ਯੌ ਉਪਜੀ ਉਪਮਾ ਰਿਤੁ ਪਾਵਸ ਅਭ੍ਰਨ ਮੈ ਦਿਨ ਰਾਜ ਫਬੈ। ੧੧੬੧।","roman":"Man yau upjee upmaa ritu paavas abhran mai din raaj phabai | 1161 |","meaning_en":"","page":523}]},{"type":"verse","number":[1162],"number_text":"੧੧੬੨।","page":523,"lines":[{"gurmukhi":"ਹਲੁ ਪਾਨਿ ਸੰਭਾਰਿ ਲਯੋ ਮੁਸਲੀ ਰਨ ਮੈ ਅਰਿ ਕੋ ਹਯ ਚਾਰੋ ਹੀ ਘਾਏ।","roman":"Halu paani sanbhaari layo muslee ran mai ari ko hay chaaro hee ghaae |","meaning_en":"","page":523},{"gurmukhi":"ਬਾਨ ਕਮਾਨ ਗਹੀ ਬਸੁਦੇਵ ਭਲੇ ਰਥ ਕੇ ਚਕ ਕਾਟਿ ਗਿਰਾਏ।","roman":"Baan kamaan gahee basudev bhale rath ke chak kaati giraae |","meaning_en":"","page":523},{"gurmukhi":"ਸਾਤਕਿ ਸੂਤ ਕੋ ਸੀਸ ਕਟਿਯੋ ਰਿਸਿ ਊਧਵ ਬਾਨ ਅਨੇਕ ਚਲਾਏ।","roman":"Saatki soot ko sees katiyo risi oodhav baan anek chalaae |","meaning_en":"","page":523},{"gurmukhi":"ਫਾਧਿ ਪਰਿਯੋ ਰਥ ਤੇ ਤਤਕਾਲ ਲਏ ਅਸਿ ਢਾਲ ਬਡੇ ਭਟ ਘਾਏ। ੧੧੬੨।","roman":"Phaadhi pariyo rath te tatkaal lae asi dhaal bade bhat ghaae | 1162 |","meaning_en":"","page":523}]},{"type":"verse","number":[1163],"number_text":"੧੧੬੩।","page":523,"lines":[{"gurmukhi":"ਠਾਢੋ ਹੁਤੋ ਭਟ ਸ੍ਰੀ ਜਦੁਬੀਰ ਕੋ ਸੋ ਅਣਗੇਸ ਜੂ ਨੈਨ ਨਿਹਾਰਿਯੋ।","roman":"Thaadho huto bhat sree jadubeer ko so anges joo nain nihaariyo |","meaning_en":"","page":523},{"gurmukhi":"ਪਾਇਨ ਕੀ ਕਰਿ ਚੰਚਲਤਾ ਬਰ ਸੋ ਅਸਿ ਸਤ੍ਰ ਕੇ ਸੀਸ ਪ੍ਰਹਾਰਿਯੋ।","roman":"Paain kee kari chanchaltaa bar so asi satr ke sees prahaariyo |","meaning_en":"","page":523},{"gurmukhi":"ਟੂਟਿ ਪਰਿਯੋ ਝਟਦੈ ਕਟਿਯੋ ਸਿਰ ਤਾ ਛਬਿ ਕੋ ਕਬਿ ਭਾਉ ਉਚਾਰਿਯੋ।","roman":"Tooti pariyo jhatdai katiyo sir taa chhabi ko kabi bhaau uchaariyo |","meaning_en":"","page":523},{"gurmukhi":"ਮਾਨਹੁ ਰਾਹੁ ਨਿਸਾ ਕਰ ਕੋ ਨਭਿ ਮੰਡਲ ਤੇ ਹਨਿ ਕੈ ਛਿਤਿ ਡਾਰਿਯੋ। ੧੧੬੩।","roman":"Maanhu raahu nisaa kar ko nabhi mandal te hani kai chhiti daariyo | 1163 |","meaning_en":"","page":523}]},{"type":"verse","number":[1164],"number_text":"੧੧੬੪।","page":523,"lines":[{"gurmukhi":"ਕੂਦਿ ਚੜਿਯੋ ਅਰਿ ਕੇ ਰਥ ਊਪਰਿ ਸਾਰਥੀ ਕਉ ਬਧ ਕੈ ਤਬ ਹੀ।","roman":"Koodi chariyo ari ke rath oopri saarthee kau badh kai tab hee |","meaning_en":"","page":523},{"gurmukhi":"ਧਨੁ ਬਾਨ ਕ੍ਰਿਪਾਨ ਗਦਾ ਬਰਛੀ ਅਰਿ ਕੇ ਕਰਿ ਸਸਤ੍ਰ ਲਏ ਸਬ ਹੀ।","roman":"Dhanu baan kripaan gadaa barchhee ari ke kari sasatr lae sab hee |","meaning_en":"","page":523},{"gurmukhi":"ਰਥ ਆਪ ਹੀ ਹਾਕ ਹੈ ਸ੍ਯਾਮ ਕਹੈ ਮਧਿ ਜਾਦਵ ਸੈਨ ਪਰਿਯੋ ਜਬ ਹੀ।","roman":"Rath aap hee haak hai syaam kahai madhi jaadav sain pariyo jab hee |","meaning_en":"","page":523},{"gurmukhi":"ਇਕ ਮਾਰਿ ਲਏ ਇਕ ਭਾਜਿ ਗਏ ਇਕ ਠਾਢਿ ਭਏ ਤੇਊ ਨ ਦਬ ਹੀ। ੧੧੬੪।","roman":"Ik maari lae ik bhaaji gae ik thaadhi bhae teoo na dab hee | 1164 |","meaning_en":"","page":523}]},{"type":"verse","number":[1165],"number_text":"੧੧੬੫।","page":523,"lines":[{"gurmukhi":"ਆਪਨ ਹੀ ਰਥ ਹਾਕਤ ਹੈ ਅਰੁ ਆਪਨ ਹੀ ਸਰ ਜਾਲ ਚਲਾਵੈ।","roman":"Aapan hee rath haakat hai aru aapan hee sar jaal chalaavai |","meaning_en":"","page":523},{"gurmukhi":"ਆਪਨ ਹੀ ਰਿਪੁ ਘਾਇ ਬਚਾਵਤ ਆਪਨ ਹੀ ਅਰਿ ਘਾਇ ਲਗਾਵੈ।","roman":"Aapan hee ripu ghaai bachaavat aapan hee ari ghaai lagaavai |","meaning_en":"","page":523},{"gurmukhi":"ਏਕਨ ਕੇ ਧਨੁ ਬਾਨ ਕਟੇ ਭਟ ਏਕਨ ਕੇ ਰਥ ਕਾਟਿ ਗਿਰਾਵੈ।","roman":"Ekan ke dhanu baan kate bhat ekan ke rath kaati giraavai |","meaning_en":"","page":523},{"gurmukhi":"ਦਾਮਨਿ ਜਿਉ ਦਮਕੈ ਘਟ ਮੈ ਕਰ ਮੈ ਕਰਵਾਰਹਿ ਤਿਉ ਚਮਕਾਵੈ। ੧੧੬੫।","roman":"Daamni jiu damkai ghat mai kar mai karvaarhi tiu chamkaavai | 1165 |","meaning_en":"","page":523}]},{"type":"verse","number":[1166],"number_text":"੧੧੬੬।","page":523,"lines":[{"gurmukhi":"ਮਾਰਿ ਕੈ ਬੀਰ ਘਨੇ ਰਨ ਮੈ ਬਹੁ ਕੋਪ ਕੈ ਦਾਤਨ ਓਠ ਚਬਾਵੈ।","roman":"Maari kai beer ghane ran mai bahu kop kai daatan oth chabaavai |","meaning_en":"","page":523},{"gurmukhi":"ਆਵਤ ਜੋ ਇਹ ਕੇ ਅਰਿ ਊਪਰਿ ਬਾਨਨ ਸਿਉ ਤਿਹ ਕਾਟਿ ਗਿਰਾਵੈ।","roman":"Aavat jo ih ke ari oopri baanan siu tih kaati giraavai |","meaning_en":"","page":523},{"gurmukhi":"ਧਾਇ ਪਰੈ ਰਿਪੁ ਕੇ ਦਲ ਮੈ ਦਲ ਕੈ ਮਲ ਕੈ ਬਹੁਰੋ ਫਿਰਿ ਆਵੈ।","roman":"Dhaai parai ripu ke dal mai dal kai mal kai bahuro phiri aavai |","meaning_en":"","page":524},{"gurmukhi":"ਜੁਧੁ ਕਰੈ ਨ ਡਰੈ ਹਰਿ ਸੋ ਅਰਿ ਕੇ ਰਥ ਕੋ ਬਲਿ ਓਰਿ ਚਲਾਵੈ। ੧੧੬੬।","roman":"Judhu karai na darai hari so ari ke rath ko bali ori chalaavai | 1166 |","meaning_en":"","page":524}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":524},{"type":"verse","number":[1167],"number_text":"੧੧੬੭।","page":524,"lines":[{"gurmukhi":"ਜਬ ਰਿਪੁ ਰਨ ਕੀਨੋ ਘਨੋ ਬਢਿਯੋ ਕ੍ਰਿਸਨ ਤਬ ਤੇਹੁ।","roman":"Jab ripu ran keeno ghano badhiyo krisan tab tehu |","meaning_en":"","page":524},{"gurmukhi":"ਜਾਦਵ ਪ੍ਰਤਿ ਹਰਿ ਯੌ ਕਹਿਯੋ ਦੁਬਿਧਾ ਕਰਿ ਹਨਿ ਲੇਹੁ। ੧੧੬੭।","roman":"Jaadav prati hari yau kahiyo dubidhaa kari hani lehu | 1167 |","meaning_en":"","page":524}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":524},{"type":"verse","number":[1168],"number_text":"੧੧੬੮।","page":524,"lines":[{"gurmukhi":"ਸਾਤਕਿ ਕਾਟਿ ਦਯੋ ਤਿਨ ਕੋ ਰਥ ਕਾਨ੍ਹ ਤਬੈ ਹਯ ਕਾਟਿ ਕੈ ਡਾਰਿਯੋ।","roman":"Saatki kaati dayo tin ko rath kaanh tabai hay kaati kai daariyo |","meaning_en":"","page":524},{"gurmukhi":"ਸੂਤ ਕੋ ਸੀਸ ਕਟਿਯੋ ਮੁਸਲੀ ਬਰਮਾਕ੍ਰਿਤ ਅੰਗ ਪ੍ਰਤੰਗ ਪ੍ਰਹਾਰਿਯੋ।","roman":"Soot ko sees katiyo muslee barmaakrit ang pratang prahaariyo |","meaning_en":"","page":524},{"gurmukhi":"ਬਾਨ ਅਕ੍ਰੂਰ ਹਨ੍ਯੋ ਉਰ ਮੈ ਤਿਹ ਜੋਰ ਲਗਿਯੋ ਨਹਿ ਨੈਕੁ ਸੰਭਾਰਿਯੋ।","roman":"Baan akroor hanyo ur mai tih jor lagiyo nahi naiku sanbhaariyo |","meaning_en":"","page":524},{"gurmukhi":"ਮੂਰਛ ਹ੍ਵੈ ਰਨਭੂਮਿ ਗਿਰਿਯੋ ਅਸਿ ਲੈ ਕਰਿ ਊਧਵ ਸੀਸ ਉਤਾਰਿਯੋ। ੧੧੬੮।","roman":"Moorachh hvai ranbhoomi giriyo asi lai kari oodhav sees utaariyo | 1168 |","meaning_en":"","page":524}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":524},{"type":"verse","number":[1169],"number_text":"੧੧੬੯।","page":524,"lines":[{"gurmukhi":"ਅਣਗ ਸਿੰਘ ਜਬ ਮਾਰਯੋ ਖਟ ਸੁਭਟਨ ਮਿਲਿ ਠਉਰ।","roman":"Anag singh jab maaryo khat subhtan mili thaur |","meaning_en":"","page":524},{"gurmukhi":"ਜਰਾਸੰਧਿ ਕੀ ਸੈਨ ਤੇ ਚਲੇ ਚਤ੍ਰ ਨ੍ਰਿਪ ਅਉਰ। ੧੧੬੯।","roman":"Jaraasandhi kee sain te chale chatr nrip aur | 1169 |","meaning_en":"","page":524}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":524},{"type":"verse","number":[1170],"number_text":"੧੧੭੦।","page":524,"lines":[{"gurmukhi":"ਅਮਿਤੇਸ ਬਲੀ ਅਚਲੇਸ ਮਹਾ ਅਨਘੇਸਹਿ ਲੈ ਅਸੁਰੇਸ ਸਿਧਾਏ।","roman":"Amites balee achles mahaa angheshi lai asures sidhaae |","meaning_en":"","page":524},{"gurmukhi":"ਬਾਨ ਕਮਾਨ ਕ੍ਰਿਪਾਨ ਬਡੇ ਬਰਛੇ ਪਰਸੇ ਸੁ ਗਦਾ ਗਹਿ ਆਏ।","roman":"Baan kamaan kripaan bade barchhe parse su gadaa gahi aae |","meaning_en":"","page":524},{"gurmukhi":"ਰੋਸ ਕੈ ਬੀਰ ਨਿਸੰਕ ਭਿਰੇ ਭਟ ਕੇ ਨ ਟਿਕੇ ਭਟ ਓਘ ਪਰਾਏ।","roman":"Ros kai beer nisank bhire bhat ke na tike bhat ogh paraae |","meaning_en":"","page":524},{"gurmukhi":"ਆਇ ਘਿਰਿਯੋ ਬ੍ਰਿਜ ਭੂਖਨ ਕਉ ਮਧੁ ਦੂਖਨ ਕਉ ਬਹੁ ਬਾਨ ਲਗਾਏ। ੧੧੭੦।","roman":"Aai ghiriyo brij bhookhan kau madhu dookhan kau bahu baan lagaae | 1170 |","meaning_en":"","page":524}]},{"type":"verse","number":[1171],"number_text":"੧੧੭੧।","page":524,"lines":[{"gurmukhi":"ਘਾਇਨ ਕਉ ਸਹਿ ਕੈ ਬ੍ਰਿਜ ਰਾਜ ਸਰਾਸਨ ਲੈ ਸਰ ਲੇਤ ਭਯੋ।","roman":"Ghaain kau sahi kai brij raaj saraasan lai sar let bhayo |","meaning_en":"","page":524},{"gurmukhi":"ਅਸੁਰੇਸਹਿ ਕੋ ਸਿਰ ਕਾਟਿ ਦਯੋ ਅਮਿਤੇਸ ਕੀ ਦੇਹ ਬਿਦਾਰਿ ਛਯੋ।","roman":"Asureshi ko sir kaati dayo amites kee deh bidaari chhayo |","meaning_en":"","page":524},{"gurmukhi":"ਅਨਘੇਸ ਕੋ ਕਾਟਿ ਦੁਖੰਡ ਕੀਯੋ ਮ੍ਰਿਤ ਹ੍ਵੈ ਰਥ ਤੇ ਗਿਰਿ ਭੂਮਿ ਪਯੋ।","roman":"Anghes ko kaati dukhand keeyo mrit hvai rath te giri bhoomi payo |","meaning_en":"","page":524},{"gurmukhi":"ਅਚਲੇਸ ਜੂ ਬਾਨਨ ਕੋ ਸਹਿ ਕੈ ਫਿਰਿ ਠਾਢਿ ਰਹਿਯੋ ਨਰਿ ਭਾਜਿ ਗਯੋ। ੧੧੭੧।","roman":"Achles joo baanan ko sahi kai phiri thaadhi rahiyo nari bhaaji gayo | 1171 |","meaning_en":"","page":524}]},{"type":"verse","number":[1172],"number_text":"੧੧੭੨।","page":524,"lines":[{"gurmukhi":"ਕੋਪ ਕੈ ਬੋਲਤ ਯੌ ਹਰਿ ਕੋ ਰਨ ਸਿੰਘ ਤੇ ਆਦਿ ਤੈ ਬੀਰ ਖਪਾਏ।","roman":"Kop kai bolat yau hari ko ran singh te aadi tai beer khapaae |","meaning_en":"","page":524},{"gurmukhi":"ਤੋ ਤੇ ਕਹੀ ਗਜ ਸਿੰਘ ਹਨ੍ਯੋ ਅਣਗੇਸ ਜੂ ਤੈ ਛਲ ਸਾਥ ਗਿਰਾਏ।","roman":"To te kahee gaj singh hanyo anges joo tai chhal saath giraae |","meaning_en":"","page":524},{"gurmukhi":"ਜਾਨਤ ਹੌ ਅਮਿਤੇਸ ਬਲੀ ਧਨ ਸਿੰਘ ਸੰਘਾਰ ਕੈ ਬੀਰ ਕਹਾਏ।","roman":"Jaanat hau amites balee dhan singh sanghaar kai beer kahaae |","meaning_en":"","page":524},{"gurmukhi":"ਸੋ ਤਬ ਲਉ ਗਜ ਗਾਜਤ ਹੈ ਜਬ ਲਉ ਬਨ ਮੈ ਮ੍ਰਿਗਰਾਜ ਨ ਆਏ। ੧੧੭੨।","roman":"So tab lau gaj gaajat hai jab lau ban mai mrigraaj na aae | 1172 |","meaning_en":"","page":524}]},{"type":"verse","number":[1173],"number_text":"੧੧੭੩।","page":525,"lines":[{"gurmukhi":"ਯੌ ਕਹਿ ਕੈ ਬਤੀਯਾ ਹਰਿ ਸੋ ਅਭਿਮਾਨ ਭਰੇ ਧਨੁ ਬਾਨ ਸੰਭਾਰਿਯੋ।","roman":"Yau kahi kai bateeyaa hari so abhimaan bhare dhanu baan sanbhaariyo |","meaning_en":"","page":525},{"gurmukhi":"ਕਾਨ ਪ੍ਰਮਾਨ ਸਰਾਸਨ ਤਾਨਿ ਮਹਾ ਸਰ ਤੀਛਨ ਸ੍ਯਾਮ ਕੋ ਮਾਰਿਯੋ।","roman":"Kaan pramaan saraasan taani mahaa sar teechhan syaam ko maariyo |","meaning_en":"","page":525},{"gurmukhi":"ਲਾਗ ਗਯੋ ਹਰਿ ਕੇ ਉਰ ਮੈ ਹਰਿ ਜੂ ਨਹਿ ਆਵਤ ਨੈਨ ਨਿਹਾਰਿਯੋ।","roman":"Laag gayo hari ke ur mai hari joo nahi aavat nain nihaariyo |","meaning_en":"","page":525},{"gurmukhi":"ਮੂਰਛਤ ਹ੍ਵੈ ਰਥ ਮਾਝਿ ਗਿਰੇ ਤਜਿ ਕੈ ਰਨ ਲੈ ਪ੍ਰਭ ਸੂਤ ਪਧਾਰਿਯੋ। ੧੧੭੩।","roman":"Moorchhat hvai rath maajhi gire taji kai ran lai prabh soot padhaariyo | 1173 |","meaning_en":"","page":525}]},{"type":"verse","number":[1174],"number_text":"੧੧੭੪।","page":525,"lines":[{"gurmukhi":"ਏਕ ਮਹੂਰਤ ਬੀਤਿ ਗਯੋ ਤਬ ਸ੍ਯੰਦਨ ਪੈ ਜਦੁਬੀਰ ਸੰਭਾਰਿਯੋ।","roman":"Ek mahoorat beeti gayo tab syandan pai jadubeer sanbhaariyo |","meaning_en":"","page":525},{"gurmukhi":"ਤਉ ਅਚਲੇਸ ਗੁਮਾਨ ਭਰੇ ਅਤਿ ਹੀ ਹਸ ਕੈ ਇਹ ਭਾਤਿ ਪੁਕਾਰਿਯੋ।","roman":"Tau achles gumaan bhare ati hee has kai ih bhaati pukaariyo |","meaning_en":"","page":525},{"gurmukhi":"ਜਾਤ ਕਹਾ ਹਮ ਤੇ ਭਜਿ ਕੈ ਕਰਿ ਲੈ ਕੇ ਗਦਾ ਕਟੁ ਬੋਲ ਉਚਾਰਿਯੋ।","roman":"Jaat kahaa ham te bhaji kai kari lai ke gadaa katu bol uchaariyo |","meaning_en":"","page":525},{"gurmukhi":"ਮਾਨਹੁ ਕੇਹਰਿ ਜਾਤ ਹੁਤੋ ਨਰ ਲੈ ਲਕੁਟੀ ਕਰਿ ਮੈ ਲਲਕਾਰਿਯੋ। ੧੧੭੪।","roman":"Maanhu kehri jaat huto nar lai lakutee kari mai lalkaariyo | 1174 |","meaning_en":"","page":525}]},{"type":"verse","number":[1175],"number_text":"੧੧੭੫।","page":525,"lines":[{"gurmukhi":"ਯੌ ਸੁਨਿ ਕੈ ਬਤੀਆ ਅਰਿ ਕੀ ਰਥੁ ਹਾਕਿ ਫਿਰਿਯੋ ਹਰਿ ਕੋਪ ਭਯੋ।","roman":"Yau suni kai bateeaa ari kee rathu haaki phiriyo hari kop bhayo |","meaning_en":"","page":525},{"gurmukhi":"ਪਟਪੀਤ ਮਹਾ ਫਹਰਿਓ ਧੁਜ ਜਿਉ ਘਨ ਮੈ ਚਪਲਾ ਸਮ ਰੂਪ ਲਯੋ।","roman":"Patpeet mahaa phahrio dhuj jiu ghan mai chaplaa sam roop layo |","meaning_en":"","page":525},{"gurmukhi":"ਬਰਖਿਯੋ ਸਰ ਬੂੰਦਨ ਜਿਉ ਘਨਿ ਸ੍ਯਾਮ ਤਬੈ ਰਿਪੁ ਕੋ ਦਲ ਮਾਰ ਦਯੋ।","roman":"Barkhiyo sar boondan jiu ghani syaam tabai ripu ko dal maar dayo |","meaning_en":"","page":525},{"gurmukhi":"ਰਿਸ ਕੈ ਅਚਲੇਸ ਸੁ ਬਾਨ ਕਮਾਨ ਗਹੋ ਹਰਿ ਸਾਮੁਹੇ ਆਇ ਖਯੋ। ੧੧੭੫।","roman":"Ris kai achles su baan kamaan gaho hari saamuhe aai khayo | 1175 |","meaning_en":"","page":525}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":525},{"type":"verse","number":[1176],"number_text":"੧੧੭੬।","page":525,"lines":[{"gurmukhi":"ਸਿੰਘ ਨਾਦ ਤਬ ਤਿਨ ਕੀਓ ਕ੍ਰਿਸਨ ਚਿਤੈ ਕਰਿ ਨੈਨ।","roman":"Singh naad tab tin keeo krisan chitai kari nain |","meaning_en":"","page":525},{"gurmukhi":"ਬਿਕਟਿ ਨਿਕਟਿ ਰਨਿ ਸੁਭਟ ਲਖਿ ਹਰਿ ਪ੍ਰਤਿ ਬੋਲਿਯੋ ਬੈਨ। ੧੧੭੬।","roman":"Bikti nikti rani subhat lakhi hari prati boliyo bain | 1176 |","meaning_en":"","page":525}]},{"type":"heading","kind":"speaker","name":"ਅਚਲ ਸਿੰਘ ਬਾਚ","gurmukhi":"ਅਚਲ ਸਿੰਘ ਬਾਚ","roman":"Achal singh baach","meaning_en":"","page":525},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":525},{"type":"verse","number":[1177],"number_text":"੧੧੭੭।","page":525,"lines":[{"gurmukhi":"ਜੀਵਤ ਜੇ ਜਗ ਮੈ ਰਹਿ ਹੈ ਅਤਿ ਜੁਧ ਕਥਾ ਹਮਰੀ ਸੁਨ ਲੈ ਹੈ।","roman":"Jeevat je jag mai rahi hai ati judh kathaa hamree sun lai hai |","meaning_en":"","page":525},{"gurmukhi":"ਤਾ ਛਬਿ ਕੀ ਕਵਿਤਾ ਕਰਿ ਕੈ ਕਬਿ ਰਾਮ ਨਰੇਸਨ ਜਾਇ ਰਿਝੈ ਹੈ।","roman":"Taa chhabi kee kavitaa kari kai kabi raam naresan jaai rijhai hai |","meaning_en":"","page":525},{"gurmukhi":"ਜੋ ਬਲਿ ਪੈ ਕਹਿ ਹੈ ਕਥ ਪੰਡਿਤ ਰੀਝਿ ਘਨੋ ਤਿਹ ਕੋ ਧਨੁ ਦੇ ਹੈ।","roman":"Jo bali pai kahi hai kath pandit reejhi ghano tih ko dhanu de hai |","meaning_en":"","page":525},{"gurmukhi":"ਹੇ ਹਰਿ ਜੂ ਇਹ ਆਹਵ ਕੇ ਜੁਗ ਚਾਰਨਿ ਮੈ ਗੁਨ ਗੰਧ੍ਰਬ ਗੈਹੈ। ੧੧੭੭।","roman":"He hari joo ih aahav ke jug chaarni mai gun gandhrab gaihai | 1177 |","meaning_en":"","page":525}]},{"type":"verse","number":[1178],"number_text":"੧੧੭੮।","page":525,"lines":[{"gurmukhi":"ਕੋਪ ਕੈ ਉਤਰ ਦੇਤ ਭਯੋ ਅਰਿ ਕੀ ਬਤੀਯਾ ਸੁਨਿ ਸ੍ਯਾਮ ਸਬੈ।","roman":"Kop kai utar det bhayo ari kee bateeyaa suni syaam sabai |","meaning_en":"","page":525},{"gurmukhi":"ਚਿਰੀਯਾ ਬਨ ਮੈ ਚੁਹਕੈ ਤਬ ਲਉ ਅਤਿ ਕੋਪ ਨ ਆਵਤ ਬਾਜ ਜਬੈ।","roman":"Chireeyaa ban mai chuhkai tab lau ati kop na aavat baaj jabai |","meaning_en":"","page":525},{"gurmukhi":"ਗਰਬਾਤ ਹੈ ਮੂਢ ਘਨੋ ਰਨ ਮੈ ਕਟਿ ਹੌ ਤੁਹਿ ਸੀਸ ਲਖੈਗੋ ਤਬੈ।","roman":"Garbaat hai moodh ghano ran mai kati hau tuhi sees lakhaigo tabai |","meaning_en":"","page":525},{"gurmukhi":"ਤਿਹ ਤੇ ਤਜਿ ਸੰਕ ਨਿਸੰਕ ਲਰੋ ਬਲਬੀਰ ਕਹਿਯੋ ਕਹਾ ਢੀਲ ਅਬੈ। ੧੧੭੮।","roman":"Tih te taji sank nisank laro balbeer kahiyo kahaa dheel abai | 1178 |","meaning_en":"","page":525}]},{"type":"verse","number":[1179],"number_text":"੧੧੭੯।","page":525,"lines":[{"gurmukhi":"ਯੌ ਸੁਨਿ ਕੈ ਕਟੁ ਬੈਨਨ ਕੋ ਅਚਲੇਸ ਬਲੀ ਮਨਿ ਕੋਪ ਜਗਿਯੋ।","roman":"Yau suni kai katu bainan ko achles balee mani kop jagiyo |","meaning_en":"","page":525},{"gurmukhi":"ਕਸ ਬੋਲਤ ਹੋ ਕਛੁ ਲਾਜ ਗਹੋ ਰਨਿ ਠਾਢੇ ਰਹੋ ਸੁਨਿ ਹੋ ਨ ਭਗਿਯੋ।","roman":"Kas bolat ho kachhu laaj gaho rani thaadhe raho suni ho na bhagiyo |","meaning_en":"","page":525},{"gurmukhi":"ਯਹ ਉਤਰ ਦੈ ਹਰਿ ਕੋ ਜਬ ਹੀ ਤਬ ਹੀ ਨਿਜ ਆਯੁਧ ਲੈ ਉਮਗਿਯੋ।","roman":"Yah utar dai hari ko jab hee tab hee nij aayudh lai umgiyo |","meaning_en":"","page":526},{"gurmukhi":"ਮਨ ਮੈ ਹਰਖਿਯੋ ਧਨੁ ਕੋ ਕਰਖਿਯੋ ਬਰਖਿਯੋ ਸਰ ਸ੍ਰੀ ਹਰਿ ਕੋ ਨ ਲਗਿਯੋ। ੧੧੭੯।","roman":"Man mai harkhiyo dhanu ko karkhiyo barkhiyo sar sree hari ko na lagiyo | 1179 |","meaning_en":"","page":526}]},{"type":"verse","number":[1180],"number_text":"੧੧੮੦।","page":526,"lines":[{"gurmukhi":"ਜੋ ਅਚਲੇਸ ਜੂ ਬਾਨ ਚਲਾਵਤ ਸੋ ਹਰਿ ਆਵਤ ਕਾਟਿ ਗਿਰਾਵੈ।","roman":"Jo achles joo baan chalaavat so hari aavat kaati giraavai |","meaning_en":"","page":526},{"gurmukhi":"ਜਾਨੈ ਨ ਦੇਹ ਲਗਿਯੋ ਅਰਿ ਕੀ ਸਰ ਫੇਰਿ ਰਿਸਾ ਕਰਿ ਅਉਰ ਚਲਾਵੈ।","roman":"Jaanai na deh lagiyo ari kee sar pheri risaa kari aur chalaavai |","meaning_en":"","page":526},{"gurmukhi":"ਸੋ ਹਰਿ ਆਵਤ ਬੀਚ ਕਟੈ ਅਪਨੋ ਉਹ ਕੋ ਉਰ ਬੀਚ ਲਗਾਵੈ।","roman":"So hari aavat beech katai apno uh ko ur beech lagaavai |","meaning_en":"","page":526},{"gurmukhi":"ਦੇਖਿ ਸਤਕ੍ਰਿਤ ਕਉਤਕ ਕੋ ਕਬਿ ਰਾਮ ਕਹੈ ਪ੍ਰਭ ਕੋ ਜਸੁ ਗਾਵੈ। ੧੧੮੦।","roman":"Dekhi satkrit kautak ko kabi raam kahai prabh ko jasu gaavai | 1180 |","meaning_en":"","page":526}]},{"type":"verse","number":[1181],"number_text":"੧੧੮੧।","page":526,"lines":[{"gurmukhi":"ਦਾਰੁਕ ਕੋ ਕਹਿਓ ਤੇਜ ਕੈ ਸ੍ਯੰਦਨ ਸ੍ਰੀ ਹਰਿ ਜੂ ਕਰਿ ਖਗੁ ਸੰਭਾਰਿਯੋ।","roman":"Daaruk ko kahio tej kai syandan sree hari joo kari khagu sanbhaariyo |","meaning_en":"","page":526},{"gurmukhi":"ਦਾਮਨਿ ਜਿਉ ਘਨ ਮੈ ਲਸਕੈ ਰਿਸ ਮੈ ਬਰਿ ਕੈ ਅਰਿ ਊਪਰ ਮਾਰਿਯੋ।","roman":"Daamni jiu ghan mai laskai ris mai bari kai ari oopar maariyo |","meaning_en":"","page":526},{"gurmukhi":"ਦੁਜਨ ਕੋ ਸਿਰੁ ਕਾਟਿ ਦਯੋ ਬਿਨੁ ਰੁੰਡ ਭਯੇ ਜਸੁ ਤਾਹਿ ਉਚਾਰਿਯੋ।","roman":"Dujan ko siru kaati dayo binu rund bhaye jasu taahi uchaariyo |","meaning_en":"","page":526},{"gurmukhi":"ਜਿਉ ਸਰਦੂਲ ਮਹਾ ਬਨ ਮੈ ਹਤ ਕੈ ਬਲ ਸੋ ਮਨੋ ਕੇਹਰਿ ਡਾਰਿਯੋ। ੧੧੮੧।","roman":"Jiu sardool mahaa ban mai hat kai bal so mano kehri daariyo | 1181 |","meaning_en":"","page":526}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":526},{"type":"verse","number":[1182],"number_text":"੧੧੮੨।","page":526,"lines":[{"gurmukhi":"ਅਡਰ ਸਿੰਘ ਅਉ ਅਜਬ ਸਿੰਘ ਅਘਟ ਸਿੰਘ ਸਿੰਘ ਬੀਰ।","roman":"Adar singh au ajab singh aghat singh singh beer |","meaning_en":"","page":526},{"gurmukhi":"ਅਮਰ ਸਿੰਘ ਅਰੁ ਅਟਲ ਸਿੰਘ ਮਹਾ ਰਥੀ ਰਨ ਧੀਰ। ੧੧੮੨।","roman":"Amar singh aru atal singh mahaa rathee ran dheer | 1182 |","meaning_en":"","page":526}]},{"type":"verse","number":[1183],"number_text":"੧੧੮੩।","page":526,"lines":[{"gurmukhi":"ਅਰਜਨ ਸਿੰਘ ਅਰੁ ਅਮਿਟ ਸਿੰਘ ਕ੍ਰਿਸਨ ਨਿਹਾਰਿਓ ਨੈਨ।","roman":"Arjan singh aru amit singh krisan nihaario nain |","meaning_en":"","page":526},{"gurmukhi":"ਆਠ ਭੂਪ ਮਿਲਿ ਪਰਸਪਰ ਬੋਲਤ ਐਸੇ ਬੈਨ। ੧੧੮੩।","roman":"Aath bhoop mili paraspar bolat aise bain | 1183 |","meaning_en":"","page":526}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":526},{"type":"verse","number":[1184],"number_text":"੧੧੮੪।","page":526,"lines":[{"gurmukhi":"ਦੇਖਤ ਹੋ ਨ੍ਰਿਪ ਸ੍ਯਾਮ ਬਲੀ ਤਿਹ ਕੇ ਹਮ ਊਪਰਿ ਧਾਇ ਪਰੈ।","roman":"Dekhat ho nrip syaam balee tih ke ham oopri dhaai parai |","meaning_en":"","page":526},{"gurmukhi":"ਅਪੁਨੇ ਪ੍ਰਭ ਕੋ ਮਿਲਿ ਕਾਜ ਕਰੈ ਮੁਸਲੀ ਹਰਿ ਤੇ ਨਹੀ ਨੈਕੁ ਡਰੈ।","roman":"Apune prabh ko mili kaaj karai muslee hari te nahee naiku darai |","meaning_en":"","page":526},{"gurmukhi":"ਧਨੁ ਬਾਨ ਕ੍ਰਿਪਾਨ ਗਦਾ ਪਰਸੇ ਬਰਛੇ ਗਹਿ ਤੀਛਨ ਜਾਇ ਅਰੈ।","roman":"Dhanu baan kripaan gadaa parse barchhe gahi teechhan jaai arai |","meaning_en":"","page":526},{"gurmukhi":"ਸਬ ਹੀ ਸੁ ਕਹੀ ਇਹ ਈ ਪ੍ਰਨੁ ਹੈ ਜਦੁ ਬੀਰ ਹਨੈ ਮਿਲਿ ਜੁਧ ਕਰੈ। ੧੧੮੪।","roman":"Sab hee su kahee ih ee pranu hai jadu beer hanai mili judh karai | 1184 |","meaning_en":"","page":526}]},{"type":"verse","number":[1185],"number_text":"੧੧੮੫।","page":526,"lines":[{"gurmukhi":"ਆਯੁਧ ਲੈ ਸਿਗਰੇ ਕਰ ਮੈ ਸੁ ਮੁਕੰਦ ਕੇ ਊਪਰਿ ਦਉਰ ਪਰੇ।","roman":"Aayudh lai sigre kar mai su mukand ke oopri daur pare |","meaning_en":"","page":526},{"gurmukhi":"ਸੁ ਧਵਾਇ ਕੈ ਸ੍ਯੰਦਨ ਆਨਿ ਅਰੇ ਸੰਗਿ ਚਾਰ ਅਛੂਹਨਿ ਸੂਰ ਬਰੇ।","roman":"Su dhavaai kai syandan aani are sangi chaar achhoohni soor bare |","meaning_en":"","page":526},{"gurmukhi":"ਕਬਿ ਰਾਮ ਕਹੈ ਅਤਿ ਆਹਵ ਮੈ ਅਘ ਖੰਡਨਿ ਤੇ ਨਹੀ ਨੈਕ ਡਰੇ।","roman":"Kabi raam kahai ati aahav mai agh khandni te nahee naik dare |","meaning_en":"","page":526},{"gurmukhi":"ਮਨੋ ਗਾਜਿ ਪ੍ਰਲੈ ਘਨ ਧਾਇ ਚਲਿਯੋ ਤਿਮ ਦਉਰੇ ਸੁ ਮਾਰ ਹੀ ਮਾਰ ਕਰੇ। ੧੧੮੫।","roman":"Mano gaaji pralai ghan dhaai chaliyo tim daure su maar hee maar kare | 1185 |","meaning_en":"","page":526}]},{"type":"verse","number":[1186],"number_text":"੧੧੮੬।","page":526,"lines":[{"gurmukhi":"ਧਨ ਸਿੰਘ ਅਛੂਹਨਿ ਦੁਇ ਸੰਗਿ ਲੈ ਅਨਗੇਸ ਅਛੂਹਨਿ ਤੀਨ ਸੁ ਲ੍ਯਾਏ।","roman":"Dhan singh achhoohni dui sangi lai anges achhoohni teen su lyaae |","meaning_en":"","page":526},{"gurmukhi":"ਸੋ ਤੁਮ ਸ੍ਯਾਮ ਸੁਨੋ ਛਲ ਸੋ ਰਨ ਮੈ ਦਸ ਹੂੰ ਨ੍ਰਿਪ ਮਾਰਿ ਗਿਰਾਏ।","roman":"So tum syaam suno chhal so ran mai das hoon nrip maari giraae |","meaning_en":"","page":526},{"gurmukhi":"ਚਾਰ ਅਛੂਹਨਿ ਲੈ ਹਮ ਹੂੰ ਦਲ ਤੋ ਪਰ ਆਏ ਹੈ ਕੋਪ ਬਢਾਏ।","roman":"Chaar achhoohni lai ham hoon dal to par aae hai kop badhaae |","meaning_en":"","page":527},{"gurmukhi":"ਤਾ ਤੇ ਕਹਿਯੋ ਸੁਨਿ ਲੈ ਹਮਰੋ ਗ੍ਰਿਹ ਕੋ ਤਜਿ ਆਹਵ ਜਾਹੁ ਪਰਾਏ। ੧੧੮੬।","roman":"Taa te kahiyo suni lai hamro grih ko taji aahav jaahu paraae | 1186 |","meaning_en":"","page":527}]},{"type":"heading","kind":"speaker","name":"ਕਾਨ੍ਹ ਜੂ ਬਾਚ","gurmukhi":"ਕਾਨ੍ਹ ਜੂ ਬਾਚ","roman":"Kaanh joo baach","meaning_en":"","page":527},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":527},{"type":"verse","number":[1187],"number_text":"੧੧੮੭।","page":527,"lines":[{"gurmukhi":"ਯੌ ਸੁਨਿ ਕੈ ਬਤੀਯਾ ਤਿਹ ਕੀ ਹਰਿ ਕੋਪ ਕਹਿਯੋ ਹਮ ਜੁਧ ਕਰੈਗੇ।","roman":"Yau suni kai bateeyaa tih kee hari kop kahiyo ham judh karaige |","meaning_en":"","page":527},{"gurmukhi":"ਬਾਨ ਕਮਾਨ ਗਦਾ ਗਹਿ ਕੈ ਦੋਊ ਭ੍ਰਾਤ ਸਬੈ ਅਰਿ ਸੈਨ ਹਰੈਗੇ।","roman":"Baan kamaan gadaa gahi kai do'oo bhraat sabai ari sain haraige |","meaning_en":"","page":527},{"gurmukhi":"ਸੂਰ ਸਿਵਾਦਿਕ ਤੇ ਨ ਭਜੈ ਹਨਿ ਹੈ ਤੁਮ ਕਉ ਨਹਿ ਜੂਝਿ ਮਰੈਗੇ।","roman":"Soor sivaadik te na bhajai hani hai tum kau nahi joojhi maraige |","meaning_en":"","page":527},{"gurmukhi":"ਮੇਰੁ ਹਲੈ ਸੁਖਿ ਹੈ ਨਿਧਿ ਬਾਰਿ ਤਊ ਰਨ ਕੀ ਛਿਤਿ ਤੇ ਨ ਟਰੈਗੇ। ੧੧੮੭।","roman":"Meru halai sukhi hai nidhi baari taoo ran kee chhiti te na taraige | 1187 |","meaning_en":"","page":527}]},{"type":"verse","number":[1188],"number_text":"੧੧੮੮।","page":527,"lines":[{"gurmukhi":"ਯੌ ਕਹਿ ਕੈ ਬਤੀਯਾ ਤਿਨ ਸੋ ਕਸਿ ਕੈ ਇਕ ਬਾਨੁ ਸੁ ਸ੍ਯਾਮ ਚਲਾਯੋ।","roman":"Yau kahi kai bateeyaa tin so kasi kai ik baanu su syaam chalaayo |","meaning_en":"","page":527},{"gurmukhi":"ਲਾਗਿ ਗਯੋ ਅਜਬੇਸ ਕੇ ਬਛ ਸੁ ਲਾਗਤ ਹੀ ਕਛੁ ਖੇਦੁ ਨ ਪਾਯੋ।","roman":"Laagi gayo ajbes ke bachh su laagat hee kachhu khedu na paayo |","meaning_en":"","page":527},{"gurmukhi":"ਫੇਰਿ ਹਠੀ ਹਠਿ ਕੈ ਹਰਿ ਸੋ ਇਮ ਬੈਨ ਮਹਾ ਕਰਿ ਕੋਪ ਸੁਨਾਯੋ।","roman":"Pheri hathee hathi kai hari so im bain mahaa kari kop sunaayo |","meaning_en":"","page":527},{"gurmukhi":"ਕਾ ਕਹੀਏ ਤਿਹ ਪੰਡਿਤ ਕੋ ਜਿਹ ਤੇ ਧਨੁ ਕੀ ਬਿਧਿ ਤੂੰ ਪੜਿ ਆਯੋ। ੧੧੮੮।","roman":"Kaa kahee'e tih pandit ko jih te dhanu kee bidhi toon pari aayo | 1188 |","meaning_en":"","page":527}]},{"type":"verse","number":[1189],"number_text":"੧੧੮੯।","page":527,"lines":[{"gurmukhi":"ਕੋਪ ਭਰੀ ਜਦੁਵੀ ਪ੍ਰਿਤਨਾ ਇਤ ਤੇ ਉਮਡੀ ਉਤ ਤੇ ਉਹੋ ਆਈ।","roman":"Kop bharee jaduvee pritnaa it te umdee ut te uho aaee |","meaning_en":"","page":527},{"gurmukhi":"ਮਾਰ ਹੀ ਮਾਰ ਕੀਏ ਮੁਖ ਤੇ ਕਬਿ ਰਾਮ ਕਹੈ ਜੀਯ ਰੋਸ ਬਢਾਈ।","roman":"Maar hee maar kee'e mukh te kabi raam kahai jeey ros badhaaee |","meaning_en":"","page":527},{"gurmukhi":"ਬਾਨ ਕ੍ਰਿਪਾਨ ਗਦਾ ਕੇ ਲਗੇ ਬਹੁ ਜੂਝਿ ਪਰੇ ਕਰਿ ਦੁੰਦ ਲਰਾਈ।","roman":"Baan kripaan gadaa ke lage bahu joojhi pare kari dund laraaee |","meaning_en":"","page":527},{"gurmukhi":"ਰੀਝ ਰਹੇ ਸੁਰ ਪੇਖਿ ਸਬੈ ਪੁਹਪਾਵਲਿ ਕੀ ਬਰਖਾ ਬਰਖਾਈ। ੧੧੮੯।","roman":"Reejh rahe sur pekhi sabai puhpaavli kee barkhaa barkhaaee | 1189 |","meaning_en":"","page":527}]},{"type":"verse","number":[1190],"number_text":"੧੧੯੦।","page":527,"lines":[{"gurmukhi":"ਇਤ ਤੇ ਰਨ ਮੈ ਰਿਸ ਬੀਰ ਲਰੈ ਨਭਿ ਮੈ ਬ੍ਰਹਮਾਦਿ ਸਨਾਦਿ ਨਿਹਾਰੈ।","roman":"It te ran mai ris beer larai nabhi mai brahmaadi sanaadi nihaarai |","meaning_en":"","page":527},{"gurmukhi":"ਆਗੇ ਨ ਐਸੋ ਭਯੋ ਕਬ ਹੂੰ ਰਨ ਆਪਸਿ ਮੈ ਇਮ ਬੋਲਿ ਉਚਾਰੈ।","roman":"Aage na aiso bhayo kab hoon ran aapsi mai im boli uchaarai |","meaning_en":"","page":527},{"gurmukhi":"ਜੂਝ ਪਰੇ ਤਿਹ ਸ੍ਰਉਨ ਢਰੇ ਭਰਿ ਖਪਰ ਜੁਗਨਿ ਪੀ ਕਿਲਕਾਰੈ।","roman":"Joojh pare tih sraun dhare bhari khapar jugni pee kilkaarai |","meaning_en":"","page":527},{"gurmukhi":"ਮੁੰਡਨ ਮਾਲ ਅਨੇਕ ਗੁਹੀ ਸਿਵ ਕੇ ਗਨ ਧਨਿ ਹੀ ਧਨਿ ਪੁਕਾਰੈ। ੧੧੯੦।","roman":"Mundan maal anek guhee siv ke gan dhani hee dhani pukaarai | 1190 |","meaning_en":"","page":527}]},{"type":"verse","number":[1191],"number_text":"੧੧੯੧।","page":527,"lines":[{"gurmukhi":"ਆਯੁਧ ਧਾਰਿ ਅਯੋਧਨ ਮੈ ਇਕ ਕੋਪ ਭਰੇ ਭਟ ਧਾਇ ਅਰੈ।","roman":"Aayudh dhaari ayodhan mai ik kop bhare bhat dhaai arai |","meaning_en":"","page":527},{"gurmukhi":"ਇਕ ਮਲ ਕੀ ਦਾਇਨ ਜੁਧ ਕਰੈ ਇਕ ਦੇਖ ਮਹਾ ਰਣ ਦਉਰਿ ਪਰੈ।","roman":"Ik mal kee daain judh karai ik dekh mahaa ran dauri parai |","meaning_en":"","page":527},{"gurmukhi":"ਇਕ ਰਾਮ ਹੀ ਰਾਮ ਕਹੈ ਮੁਖਿ ਤੇ ਇਕੁ ਮਾਰ ਹੀ ਮਾਰ ਇਹੈ ਉਚਰੈ।","roman":"Ik raam hee raam kahai mukhi te iku maar hee maar ihai uchrai |","meaning_en":"","page":527},{"gurmukhi":"ਇਕ ਜੂਝਿ ਪਰੇ ਇਕ ਘਾਇ ਭਰੇ ਇਕ ਸ੍ਯਾਮ ਕਹਾ ਇਹ ਭਾਤਿ ਰਰੈ। ੧੧੯੧।","roman":"Ik joojhi pare ik ghaai bhare ik syaam kahaa ih bhaati rarai | 1191 |","meaning_en":"","page":527}]},{"type":"verse","number":[1192],"number_text":"੧੧੯੨।","page":527,"lines":[{"gurmukhi":"ਮੁਕੀਯਾ ਊ ਲਰੈ ਇਕ ਅਪਾਸ ਮੈ ਗਹਿ ਕੇਸਨਿ ਕੇਸ ਏਕ ਅਰੇ ਹੈ।","roman":"Mukeeyaa oo larai ik apaas mai gahi kesni kes ek are hai |","meaning_en":"","page":527},{"gurmukhi":"ਏਕ ਚਲੇ ਰਨ ਤੇ ਭਜਿ ਕੈ ਇਕ ਆਹਵ ਕੋ ਪਗ ਆਗੇ ਕਰੇ ਹੈ।","roman":"Ek chale ran te bhaji kai ik aahav ko pag aage kare hai |","meaning_en":"","page":527},{"gurmukhi":"ਏਕ ਲਰੇ ਗਹਿ ਫੇਟਨਿ ਫੇਟ ਕਟਾਰਨ ਸੋ ਦੋਊ ਜੂਝਿ ਮਰੇ ਹੈ।","roman":"Ek lare gahi phetni phet kataaran so do'oo joojhi mare hai |","meaning_en":"","page":528},{"gurmukhi":"ਸੋਊ ਲਰੇ ਕਬਿ ਰਾਮ ਰਰੈ ਅਪੁਨੇ ਕੁਲ ਕੀ ਜੋਊ ਲਾਜਿ ਭਰੇ ਹੈ। ੧੧੯੨।","roman":"So'oo lare kabi raam rarai apune kul kee jo'oo laaji bhare hai | 1192 |","meaning_en":"","page":528}]},{"type":"verse","number":[1193],"number_text":"੧੧੯੩।","page":528,"lines":[{"gurmukhi":"ਆਠੋ ਹੀ ਭੂਪ ਅਯੋਧਨ ਮੈ ਸਬ ਲੈ ਪ੍ਰਿਤਨਾ ਹਰਿ ਊਪਰਿ ਆਏ।","roman":"Aatho hee bhoop ayodhan mai sab lai pritnaa hari oopri aae |","meaning_en":"","page":528},{"gurmukhi":"ਜੁਧ ਕਰੋ ਨ ਡਰੋ ਹਮ ਤੇ ਕਬਿ ਰਾਮ ਕਹੈ ਇਹ ਬੈਨ ਸੁਨਾਏ।","roman":"Judh karo na daro ham te kabi raam kahai ih bain sunaae |","meaning_en":"","page":528},{"gurmukhi":"ਦੈ ਕੈ ਕਸੀਸਨਿ ਈਸਨਿ ਚਾਪਨਿ ਲੈ ਸਰ ਸ੍ਰੀ ਹਰਿ ਓਰਿ ਚਲਾਏ।","roman":"Dai kai kaseesni eesni chaapni lai sar sree hari ori chalaae |","meaning_en":"","page":528},{"gurmukhi":"ਸ੍ਯਾਮ ਜੂ ਪਾਨਿ ਸਰਾਸਨਿ ਲੈ ਸਰ ਸੋ ਸਰ ਆਵਤ ਕਾਟਿ ਗਿਰਾਏ। ੧੧੯੩।","roman":"Syaam joo paani saraasni lai sar so sar aavat kaati giraae | 1193 |","meaning_en":"","page":528}]},{"type":"verse","number":[1194],"number_text":"੧੧੯੪।","page":528,"lines":[{"gurmukhi":"ਤਉ ਮਿਲਿ ਕੈ ਧੁਜਨੀ ਅਰਿ ਕੀ ਜਦੁਬੀਰ ਚਹੂੰ ਦਿਸ ਤੇ ਰਿਸਿ ਘੇਰਿਯੋ।","roman":"Tau mili kai dhujnee ari kee jadubeer chahoon dis te risi gheriyo |","meaning_en":"","page":528},{"gurmukhi":"ਆਪਸਿ ਮੈ ਮਿਲਿ ਕੈ ਭਟ ਧੀਰ ਹਨ੍ਯੋ ਬਲਬੀਰ ਇਹੈ ਪੁਨਿ ਟੇਰਿਯੋ।","roman":"Aapsi mai mili kai bhat dheer hanyo balbeer ihai puni teriyo |","meaning_en":"","page":528},{"gurmukhi":"ਸ੍ਰੀ ਧਨ ਸਿੰਘ ਬਲੀ ਅਚਲੇਸ ਕਉ ਅਉਰ ਨਰੇਸਨਿ ਯਾ ਹੀ ਨਿਬੇਰਿਯੋ।","roman":"Sree dhan singh balee achles kau aur naresni yaa hee niberiyo |","meaning_en":"","page":528},{"gurmukhi":"ਇਉ ਕਹਿ ਕੈ ਸਰ ਮਾਰਤ ਭਯੋ ਗਜ ਪੁੰਜ ਮਨੋ ਕਰਿ ਕੇਹਰਿ ਛੇਰਿਯੋ। ੧੧੯੪।","roman":"Iu kahi kai sar maarat bhayo gaj punj mano kari kehri chheriyo | 1194 |","meaning_en":"","page":528}]},{"type":"verse","number":[1195],"number_text":"੧੧੯੫।","page":528,"lines":[{"gurmukhi":"ਘੇਰਿ ਲਯੋ ਹਰਿ ਕੌ ਜਬ ਹੀ ਹਰਿ ਜੂ ਤਬ ਹੀ ਸਬ ਸਸਤ੍ਰ ਸੰਭਾਰੇ।","roman":"Gheri layo hari kau jab hee hari joo tab hee sab sasatr sanbhaare |","meaning_en":"","page":528},{"gurmukhi":"ਕੋਪਿ ਅਯੋਧਨ ਮੈ ਫਿਰਿ ਕੈ ਰਿਸ ਸਾਥ ਘਨੇ ਅਰਿ ਬੀਰ ਸੰਘਾਰੇ।","roman":"Kopi ayodhan mai phiri kai ris saath ghane ari beer sanghaare |","meaning_en":"","page":528},{"gurmukhi":"ਏਕਨ ਕੇ ਸਿਰ ਕਾਟਿ ਦਏ ਇਕ ਜੀਵਤ ਹੀ ਗਹਿ ਕੇਸਿ ਪਛਾਰੇ।","roman":"Ekan ke sir kaati dae ik jeevat hee gahi kesi pachhaare |","meaning_en":"","page":528},{"gurmukhi":"ਏਕ ਲਰੇ ਕਟਿ ਭੂਮਿ ਪਰੇ ਇਕ ਦੇਖ ਡਰੇ ਮਰਿ ਗੇ ਬਿਨੁ ਮਾਰੇ। ੧੧੯੫।","roman":"Ek lare kati bhoomi pare ik dekh dare mari ge binu maare | 1195 |","meaning_en":"","page":528}]},{"type":"verse","number":[1196],"number_text":"੧੧੯੬।","page":528,"lines":[{"gurmukhi":"ਆਠੋ ਈ ਭੂਪ ਕਹਿਓ ਮੁਖ ਤੇ ਭਟ ਭਾਜਤ ਹੋ ਕਹਾ ਜੁਧੁ ਕਰੋ।","roman":"Aatho ee bhoop kahio mukh te bhat bhaajat ho kahaa judhu karo |","meaning_en":"","page":528},{"gurmukhi":"ਜਬ ਲਉ ਰਨ ਮੈ ਹਮ ਜੀਵਤ ਹੈ ਤਬ ਲਉ ਹਰਿ ਤੇ ਤੁਮ ਹੂੰ ਨ ਡਰੋ।","roman":"Jab lau ran mai ham jeevat hai tab lau hari te tum hoon na daro |","meaning_en":"","page":528},{"gurmukhi":"ਹਮਰੋ ਇਹ ਆਇਸ ਹੈ ਤੁਮ ਕੋ ਜਦੁਬੀਰ ਕੇ ਸਾਮੁਹਿ ਜਾਇ ਲਰੋ।","roman":"Hamro ih aais hai tum ko jadubeer ke saamuhi jaai laro |","meaning_en":"","page":528},{"gurmukhi":"ਕੋਊ ਆਹਵ ਤੇ ਨਹੀ ਨੈਕੁ ਟਰੋ ਇਕ ਜੂਝਿ ਪਰੋ ਇਕ ਧਾਇ ਅਰੋ। ੧੧੯੬।","roman":"Ko'oo aahav te nahee naiku taro ik joojhi paro ik dhaai aro | 1196 |","meaning_en":"","page":528}]},{"type":"verse","number":[1197],"number_text":"੧੧੯੭।","page":528,"lines":[{"gurmukhi":"ਫੇਰਿ ਫਿਰੇ ਪਟ ਆਯੁਧ ਲੈ ਰਨ ਮੈ ਜਦੁਬੀਰ ਕਉ ਘੇਰਿ ਲੀਯੋ।","roman":"Pheri phire pat aayudh lai ran mai jadubeer kau gheri leeyo |","meaning_en":"","page":528},{"gurmukhi":"ਨ ਟਰੇ ਅਤਿ ਰੋਸਿ ਭਿਰੇ ਜੀਯ ਮੈ ਅਤਿ ਆਹਵ ਚਿਤ੍ਰ ਬਚਿਤ੍ਰ ਕੀਯੋ।","roman":"Na tare ati rosi bhire jeey mai ati aahav chitr bachitr keeyo |","meaning_en":"","page":528},{"gurmukhi":"ਅਸਿ ਲੈ ਬਰਬੀਰ ਗਦਾ ਗਹਿ ਕੈ ਰਿਪੁ ਕੋ ਦਲੁ ਮਾਰਿ ਬਿਦਾਰਿ ਦੀਯੋ।","roman":"Asi lai barbeer gadaa gahi kai ripu ko dalu maari bidaari deeyo |","meaning_en":"","page":528},{"gurmukhi":"ਇਕ ਬੀਰਨ ਕੇ ਪਦੁ ਸੀਸ ਕਟੇ ਭਟ ਏਕਨ ਕੋ ਦਯੋ ਫਾਰਿ ਹੀਯੋ। ੧੧੯੭।","roman":"Ik beeran ke padu sees kate bhat ekan ko dayo phaari heeyo | 1197 |","meaning_en":"","page":528}]},{"type":"verse","number":[1198],"number_text":"੧੧੯੮।","page":528,"lines":[{"gurmukhi":"ਸ੍ਰੀ ਜਦੁਬੀਰ ਸਰਾਸਨਿ ਲੈ ਬਹੁ ਕਾਟਿ ਰਥੀ ਸਿਰ ਭੂਮਿ ਗਿਰਾਏ।","roman":"Sree jadubeer saraasni lai bahu kaati rathee sir bhoomi giraae |","meaning_en":"","page":528},{"gurmukhi":"ਆਯੁਧ ਲੈ ਅਪੁਨੇ ਅਪੁਨੇ ਇਕ ਕੋਪਿ ਭਰੇ ਹਰਿ ਪੈ ਪੁਨਿ ਧਾਏ।","roman":"Aayudh lai apune apune ik kopi bhare hari pai puni dhaae |","meaning_en":"","page":528},{"gurmukhi":"ਤੇ ਬ੍ਰਿਜਨਾਥ ਕਰੰ ਗਹਿ ਖਗ ਅਭਗ ਹਨੇ ਸੁ ਘਨੇ ਤਹ ਘਾਏ।","roman":"Te brijnaath karan gahi khag abhag hane su ghane tah ghaae |","meaning_en":"","page":528},{"gurmukhi":"ਭਾਜਿ ਗਏ ਹਰਿ ਤੇ ਅਰਿ ਇਉ ਸੁ ਕੋਊ ਨਹਿ ਆਹਵ ਮੈ ਠਹਰਾਏ। ੧੧੯੮।","roman":"Bhaaji gae hari te ari iu su ko'oo nahi aahav mai thahraae | 1198 |","meaning_en":"","page":528}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":529},{"type":"verse","number":[1199],"number_text":"੧੧੯੯।","page":529,"lines":[{"gurmukhi":"ਭੂਪਨ ਕੀ ਭਾਜੀ ਚਮੂ ਖਾਇ ਘਨੀ ਹਰਿ ਮਾਰਿ।","roman":"Bhoopan kee bhaajee chamoo khaai ghanee hari maari |","meaning_en":"","page":529},{"gurmukhi":"ਤਬਹਿ ਫਿਰੇ ਨ੍ਰਿਪ ਜੁਧ ਕੇ ਆਯੁਧ ਸਕਲ ਸੰਭਾਰਿ। ੧੧੯੯।","roman":"Tabhi phire nrip judh ke aayudh sakal sanbhaari | 1199 |","meaning_en":"","page":529}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":529},{"type":"verse","number":[1200],"number_text":"੧੨੦੦।","page":529,"lines":[{"gurmukhi":"ਕੋਪ ਅਯੋਧਨੁ ਮੈ ਕਰਿ ਕੈ ਕਰਿ ਮੈ ਸਬ ਭੂਪਨ ਸਸਤ੍ਰ ਸੰਭਾਰੇ।","roman":"Kop ayodhnu mai kari kai kari mai sab bhoopan sasatr sanbhaare |","meaning_en":"","page":529},{"gurmukhi":"ਆਇ ਕੈ ਸਾਮੁਹੇ ਸ੍ਯਾਮ ਹੀ ਕੇ ਬਲ ਕੈ ਨਿਜੁ ਆਯੁਧ ਰੋਸਿ ਪ੍ਰਹਾਰੇ।","roman":"Aai kai saamuhe syaam hee ke bal kai niju aayudh rosi prahaare |","meaning_en":"","page":529},{"gurmukhi":"ਕਾਨ੍ਹ ਸੰਭਾਰਿ ਸਰਾਸਨਿ ਲੈ ਸਰ ਸਤ੍ਰਨ ਕਾਟਿ ਕੈ ਭੂ ਪਰਿ ਡਾਰੇ।","roman":"Kaanh sanbhaari saraasni lai sar satran kaati kai bhoo pari daare |","meaning_en":"","page":529},{"gurmukhi":"ਘਾਇ ਬਚਾਇ ਕੈ ਯੌ ਤਿਨ ਕੈ ਬਹੁਰੇ ਅਰਿ ਕੈ ਸਿਰ ਕਾਟਿ ਉਤਾਰੇ। ੧੨੦੦।","roman":"Ghaai bachaai kai yau tin kai bahure ari kai sir kaati utaare | 1200 |","meaning_en":"","page":529}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":529},{"type":"verse","number":[1201],"number_text":"੧੨੦੧।","page":529,"lines":[{"gurmukhi":"ਅਜਬ ਸਿੰਘ ਕੋ ਸਿਰ ਕਟਿਯੋ ਹਰਿ ਜੂ ਸਸਤ੍ਰ ਸੰਭਾਰਿ।","roman":"Ajab singh ko sir katiyo hari joo sasatr sanbhaari |","meaning_en":"","page":529},{"gurmukhi":"ਅਡਰ ਸਿੰਘ ਘਾਇਲ ਕਰਿਓ ਅਤਿ ਰਨ ਭੂਮਿ ਮਝਾਰਿ। ੧੨੦੧।","roman":"Adar singh ghaail kario ati ran bhoomi majhaari | 1201 |","meaning_en":"","page":529}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"","page":529},{"type":"verse","number":[1202],"number_text":"੧੨੦੨।","page":529,"lines":[{"gurmukhi":"ਅਡਰ ਸਿੰਘ ਘਾਇਲ ਜਬ ਭਯੋ। ਅਤਿ ਹੀ ਕੋਪੁ ਜੀਯ ਤਿਹ ਠਯੋ।","roman":"Adar singh ghaail jab bhayo | ati hee kopu jeey tih thayo |","meaning_en":"","page":529},{"gurmukhi":"ਬਹੁ ਤੀਛਨ ਬਰਛਾ ਤਿਨਿ ਲਯੋ। ਹਰਿ ਕੀ ਓਰਿ ਡਾਰਿ ਕੈ ਦਯੋ। ੧੨੦੨।","roman":"Bahu teechhan barchhaa tini layo | hari kee ori daari kai dayo | 1202 |","meaning_en":"","page":529}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":529},{"type":"verse","number":[1203],"number_text":"੧੨੦੩।","page":529,"lines":[{"gurmukhi":"ਬਰਛਾ ਆਵਤ ਲਖਿਯੋ ਹਰਿ ਧਨੁਖ ਬਾਨ ਕਰਿ ਕੀਨ।","roman":"Barchhaa aavat lakhiyo hari dhanukh baan kari keen |","meaning_en":"","page":529},{"gurmukhi":"ਆਵਤ ਸਰ ਸੋ ਕਾਟਿ ਕੈ ਮਾਰਿ ਵਹੈ ਭਟ ਲੀਨ। ੧੨੦੩।","roman":"Aavat sar so kaati kai maari vahai bhat leen | 1203 |","meaning_en":"","page":529}]},{"type":"verse","number":[1204],"number_text":"੧੨੦੪।","page":529,"lines":[{"gurmukhi":"ਅਘੜ ਸਿੰਘ ਲਖਿ ਤਿਹ ਦਸਾ ਦੇਤ ਭਯੋ ਨਹੀ ਪੀਠਿ।","roman":"Aghar singh lakhi tih dasaa det bhayo nahee peethi |","meaning_en":"","page":529},{"gurmukhi":"ਸਮੁਹੇ ਹਰਿ ਕੇ ਆਇ ਕੈ ਬੋਲਿਯੋ ਹ੍ਵੈ ਕਰਿ ਢੀਠੁ। ੧੨੦੪।","roman":"Samuhe hari ke aai kai boliyo hvai kari dheethu | 1204 |","meaning_en":"","page":529}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"","page":529},{"type":"verse","number":[1205],"number_text":"੧੨੦੫।","page":529,"lines":[{"gurmukhi":"ਹਰਿ ਸਨਮੁਖਿ ਇਹ ਭਾਤਿ ਉਚਾਰਿਓ। ਅਡਰ ਸਿੰਘ ਤੈ ਛਲ ਸੋ ਮਾਰਿਓ।","roman":"Hari sanmukhi ih bhaati uchaario | adar singh tai chhal so maario |","meaning_en":"","page":529},{"gurmukhi":"ਅਜਬ ਸਿੰਘ ਕਰਿ ਕਪਟ ਖਪਾਯੋ। ਇਹ ਸਭ ਭੇਦ ਹਮੋ ਲਖਿ ਪਾਯੋ। ੧੨੦੫।","roman":"Ajab singh kari kapat khapaayo | ih sabh bhed hamo lakhi paayo | 1205 |","meaning_en":"","page":529}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":529},{"type":"verse","number":[1206],"number_text":"੧੨੦੬।","page":529,"lines":[{"gurmukhi":"ਅਘੜ ਸਿੰਘ ਅਤਿ ਨਿਡਰ ਹ੍ਵੈ ਬੋਲਿਯੋ ਹਰਿ ਸਮੁਹਾਇ।","roman":"Aghar singh ati nidar hvai boliyo hari samuhaai |","meaning_en":"","page":529},{"gurmukhi":"ਬਚਨ ਸ੍ਯਾਮ ਸੌ ਜੇ ਕਹੇ ਸੋ ਕਬਿ ਕਹਿਤ ਸੁਨਾਇ। ੧੨੦੬।","roman":"Bachan syaam sau je kahe so kabi kahit sunaai | 1206 |","meaning_en":"","page":529}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":529},{"type":"verse","number":[1207],"number_text":"੧੨੦੭।","page":529,"lines":[{"gurmukhi":"ਢੀਠ ਹ੍ਵੈ ਬੋਲਤ ਭਯੋ ਰਨ ਮੈ ਹਸਿ ਕੈ ਹਰਿ ਸੋ ਬਤੀਯਾ ਸੁਨਿ ਲੈਹੋ।","roman":"Dheeth hvai bolat bhayo ran mai hasi kai hari so bateeyaa suni laiho |","meaning_en":"","page":529},{"gurmukhi":"ਕ੍ਰੁਧ ਕੀਏ ਹਮ ਸੰਗਿ ਨਿਸੰਗ ਕਹਾ ਅਬ ਜੁਧ ਕੀਏ ਫਲੁ ਪੈ ਹੋ।","roman":"Krudh kee'e ham sangi nisang kahaa ab judh kee'e phalu pai ho |","meaning_en":"","page":529},{"gurmukhi":"ਤਾ ਤੇ ਲਰੋ ਨਹੀ ਮੋ ਸੰਗਿ ਆਇ ਕੈ ਹੋ ਲਰਿਕਾ ਰਨ ਦੇਖਿ ਪਰੈ ਹੋ।","roman":"Taa te laro nahee mo sangi aai kai ho larikaa ran dekhi parai ho |","meaning_en":"","page":530},{"gurmukhi":"ਜੋ ਹਠ ਕੈ ਲਰਿ ਹੋ ਮਰਿ ਹੋ ਅਪੁਨੇ ਗ੍ਰਿਹ ਮਾਰਗਿ ਜੀਤਿ ਨ ਜੈ ਹੋ। ੧੨੦੭।","roman":"Jo hath kai lari ho mari ho apune grih maargi jeeti na jai ho | 1207 |","meaning_en":"","page":530}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":530},{"type":"verse","number":[1208],"number_text":"੧੨੦੮।","page":530,"lines":[{"gurmukhi":"ਜਿਉ ਬੋਲਿਯੋ ਅਤਿ ਗਰਬ ਸਿਉ ਇਤਿ ਹਰਿ ਐਚਿ ਕਮਾਨ।","roman":"Jiu boliyo ati garab siu iti hari aichi kamaan |","meaning_en":"","page":530},{"gurmukhi":"ਸਰ ਮਾਰਿਯੋ ਅਰਿ ਮੁਖਿ ਬਿਖੈ ਪਰਿਯੋ ਮ੍ਰਿਤਕ ਛਿਤਿ ਆਨਿ। ੧੨੦੮।","roman":"Sar maariyo ari mukhi bikhai pariyo mritak chhiti aani | 1208 |","meaning_en":"","page":530}]},{"type":"verse","number":[1209],"number_text":"੧੨੦੯।","page":530,"lines":[{"gurmukhi":"ਅਰਜਨ ਸਿੰਘ ਤਬ ਢੀਠ ਹੁਇ ਕਹੀ ਕ੍ਰਿਸਨ ਸੋ ਬਾਤ।","roman":"Arjan singh tab dheeth hui kahee krisan so baat |","meaning_en":"","page":530},{"gurmukhi":"ਮਹਾਬਲੀ ਹਉ ਆਜ ਹੀ ਕਰਿ ਹੋ ਤੇਰੋ ਘਾਤ। ੧੨੦੯।","roman":"Mahaablee hau aaj hee kari ho tero ghaat | 1209 |","meaning_en":"","page":530}]},{"type":"verse","number":[1210],"number_text":"੧੨੧੦।","page":530,"lines":[{"gurmukhi":"ਸੁਨਤ ਬਚਨ ਹਰਿ ਖਗੁ ਲੈ ਅਰਿ ਸਿਰਿ ਝਾਰਿਯੋ ਧਾਇ।","roman":"Sunat bachan hari khagu lai ari siri jhaariyo dhaai |","meaning_en":"","page":530},{"gurmukhi":"ਗਿਰਿਓ ਮਨੋ ਆਧੀ ਬਚੇ ਬਡੋ ਬ੍ਰਿਛ ਮੁਰਝਾਇ। ੧੨੧੦।","roman":"Girio mano aadhee bache bado brichh murjhaai | 1210 |","meaning_en":"","page":530}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":530},{"type":"verse","number":[1211],"number_text":"੧੨੧੧।","page":530,"lines":[{"gurmukhi":"ਅਰਜਨ ਸਿੰਘ ਹਨ੍ਯੋ ਅਸਿ ਸਿਉ ਅਮਰੇਸ ਮਹੀਪ ਹਨਿਓ ਤਬ ਹੀ।","roman":"Arjan singh hanyo asi siu amres maheep hanio tab hee |","meaning_en":"","page":530},{"gurmukhi":"ਅਟਲੇਸ ਪ੍ਰਕੋਪ ਭਯੋ ਲਖਿ ਕੈ ਹਰਿ ਆਪੁਨੇ ਸਸਤ੍ਰ ਲਏ ਸਬ ਹੀ।","roman":"Atles prakop bhayo lakhi kai hari aapune sasatr lae sab hee |","meaning_en":"","page":530},{"gurmukhi":"ਅਤਿ ਮਾਰ ਹੀ ਮਾਰ ਪੁਕਾਰਿ ਪਰਿਓ ਹਰਿ ਸਾਮੁਹੇ ਆਇ ਅਰਿਓ ਜਬ ਹੀ।","roman":"Ati maar hee maar pukaari pario hari saamuhe aai ario jab hee |","meaning_en":"","page":530},{"gurmukhi":"ਕਲਧਉਤ ਕੇ ਭੂਖਨ ਅੰਗ ਸਜੇ ਜਿਹ ਕੀ ਛਬਿ ਸੋ ਸਵਿਤਾ ਦਬ ਹੀ। ੧੨੧੧।","roman":"Kaldhaut ke bhookhan ang saje jih kee chhabi so savitaa dab hee | 1211 |","meaning_en":"","page":530}]},{"type":"verse","number":[1212],"number_text":"੧੨੧੨।","page":530,"lines":[{"gurmukhi":"ਜਾਮ ਪ੍ਰਮਾਨ ਕੀਓ ਘਮਸਾਨ ਬਡੌ ਬਲਵਾਨ ਨ ਜਾਇ ਸੰਘਾਰਿਯੋ।","roman":"Jaam pramaan keeo ghamsaan badau balvaan na jaai sanghaariyo |","meaning_en":"","page":530},{"gurmukhi":"ਮੇਘ ਜਿਉ ਗਾਜਿ ਮੁਰਾਰਿ ਤਬੈ ਅਸਿ ਲੈ ਕਰਿ ਮੈ ਅਰਿ ਊਪਰਿ ਝਾਰਿਯੋ।","roman":"Megh jiu gaaji muraari tabai asi lai kari mai ari oopri jhaariyo |","meaning_en":"","page":530},{"gurmukhi":"ਹੁਇ ਮ੍ਰਿਤ ਭੂਮਿ ਪਰਿਯੋ ਤਬ ਹੀ ਜਦੁਬੀਰ ਜਬੈ ਸਿਰੁ ਕਾਟਿ ਉਤਾਰਿਯੋ।","roman":"Hui mrit bhoomi pariyo tab hee jadubeer jabai siru kaati utaariyo |","meaning_en":"","page":530},{"gurmukhi":"ਧੰਨਿ ਹੀ ਧੰਨਿ ਕਹੈ ਸਬ ਦੇਵ ਬਡੋ ਹਰਿ ਜੂ ਭਵ ਭਾਰ ਉਤਾਰਿਯੋ। ੧੨੧੨।","roman":"Dhanni hee dhanni kahai sab dev bado hari joo bhav bhaar utaariyo | 1212 |","meaning_en":"","page":530}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":530},{"type":"verse","number":[1213],"number_text":"੧੨੧੩।","page":530,"lines":[{"gurmukhi":"ਅਟਲ ਸਿੰਘ ਜਬ ਮਾਰਿਓ ਬਹੁ ਬੀਰਨ ਕੋ ਰਾਉ।","roman":"Atal singh jab maario bahu beeran ko raau |","meaning_en":"","page":530},{"gurmukhi":"ਅਮਿਟ ਸਿੰਘ ਤਬ ਅਮਿਟ ਹੁਇ ਕੀਨੋ ਜੁਧ ਉਪਾਉ। ੧੨੧੩।","roman":"Amit singh tab amit hui keeno judh upaau | 1213 |","meaning_en":"","page":530}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":530},{"type":"verse","number":[1214],"number_text":"੧੨੧੪।","page":530,"lines":[{"gurmukhi":"ਬੋਲਤ ਇਉ ਹਠਿ ਕੈ ਹਰਿ ਸੋ ਭਟ ਤਉ ਲਖਿ ਹੋ ਜਬ ਮੋ ਸੋ ਲਰੈਗੋ।","roman":"Bolat iu hathi kai hari so bhat tau lakhi ho jab mo so laraigo |","meaning_en":"","page":530},{"gurmukhi":"ਮੋ ਕੋ ਕਹਾ ਹਨਿ ਰਾਜਨ ਜ੍ਯੋ ਛਲ ਮੂਰਤਿ ਹੁਇ ਛਲ ਸਾਥ ਛਰੈਗੋ।","roman":"Mo ko kahaa hani raajan jyo chhal moorti hui chhal saath chharaigo |","meaning_en":"","page":530},{"gurmukhi":"ਮੋ ਅਤਿ ਕੋਪ ਭਰੋ ਲਖਿ ਕੈ ਰਹਿ ਹੋ ਨਹਿ ਆਹਵ ਹੂੰ ਤੇ ਟਰੈਗੋ।","roman":"Mo ati kop bharo lakhi kai rahi ho nahi aahav hoon te taraigo |","meaning_en":"","page":530},{"gurmukhi":"ਜਉ ਕਬ ਹੂੰ ਭਿਰ ਹੋ ਹਮ ਸੋ ਨਿਸਚੈ ਨਿਜ ਦੇਹ ਕੋ ਤਿਆਗੁ ਕਰੈਗੋ। ੧੨੧੪।","roman":"Jau kab hoon bhir ho ham so nischai nij deh ko tiaagu karaigo | 1214 |","meaning_en":"","page":530}]},{"type":"verse","number":[1215],"number_text":"੧੨੧੫।","page":531,"lines":[{"gurmukhi":"ਕਾਹੇ ਕਉ ਕਾਨ੍ਹ ਅਯੋਧਨ ਮੈ ਹਿਤ ਔਰਨ ਕੇ ਰਿਸ ਕੈ ਰਨ ਪਾਰੋ।","roman":"Kaahe kau kaanh ayodhan mai hit auran ke ris kai ran paaro |","meaning_en":"","page":531},{"gurmukhi":"ਕਾਹੇ ਕਉ ਘਾਇ ਸਹੋ ਤਨ ਮੈ ਪੁਨਿ ਕਾ ਕੇ ਕਹੇ ਅਰਿ ਭੂਪਨਿ ਮਾਰੋ।","roman":"Kaahe kau ghaai saho tan mai puni kaa ke kahe ari bhoopni maaro |","meaning_en":"","page":531},{"gurmukhi":"ਜੀਵਤ ਹੋ ਤਬ ਲਉ ਜਗ ਮੈ ਜਬ ਲਉ ਮੁਹਿ ਸੰਗਿ ਭਿਰਿਓ ਨ ਬਿਚਾਰੋ।","roman":"Jeevat ho tab lau jag mai jab lau muhi sangi bhirio na bichaaro |","meaning_en":"","page":531},{"gurmukhi":"ਸੁੰਦਰ ਜਾਨ ਕੈ ਛਾਡਤ ਹੋ ਤਜਿ ਕੈ ਰਨ ਸ੍ਯਾਮ ਜੂ ਧਾਮਿ ਸਿਧਾਰੋ। ੧੨੧੫।","roman":"Sundar jaan kai chhaadat ho taji kai ran syaam joo dhaami sidhaaro | 1215 |","meaning_en":"","page":531}]},{"type":"verse","number":[1216],"number_text":"੧੨੧੬।","page":531,"lines":[{"gurmukhi":"ਫੇਰਿ ਅਯੋਧਨ ਮੈ ਰਿਸਿ ਕੇ ਅਮਿਟੇਸ ਬਲੀ ਇਹ ਭਾਤਿ ਉਚਾਰੋ।","roman":"Pheri ayodhan mai risi ke amites balee ih bhaati uchaaro |","meaning_en":"","page":531},{"gurmukhi":"ਬੈਸ ਕਿਸੋਰ ਮਨੋਹਰਿ ਮੂਰਤਿ ਲੈ ਹੋ ਕਹਾ ਲਖਿ ਜੁਧ ਹਮਾਰੋ।","roman":"Bais kisor manohri moorti lai ho kahaa lakhi judh hamaaro |","meaning_en":"","page":531},{"gurmukhi":"ਹਉ ਤੁਮ ਸਿਉ ਹਰਿ ਸਾਚ ਕਹਿਓ ਤੁਮ ਜਉ ਜੀਯ ਮੈ ਕਛੁ ਅਉਰ ਬਿਚਾਰੋ।","roman":"Hau tum siu hari saach kahio tum jau jeey mai kachhu aur bichaaro |","meaning_en":"","page":531},{"gurmukhi":"ਕੈ ਹਮ ਸੰਗਿ ਲਰੋ ਤਜਿ ਕੈ ਡਰ ਕੈ ਅਪੁਨੇ ਸਭ ਆਯੁਧ ਡਾਰੋ। ੧੨੧੬।","roman":"Kai ham sangi laro taji kai dar kai apune sabh aayudh daaro | 1216 |","meaning_en":"","page":531}]},{"type":"verse","number":[1217],"number_text":"੧੨੧੭।","page":531,"lines":[{"gurmukhi":"ਆਜੁ ਆਯੋਧਨ ਮੈ ਤੁਮ ਕੋ ਹਨਿ ਹੋ ਤੁਮਰੀ ਸਭ ਹੀ ਪ੍ਰਿਤਨਾ ਕੋ।","roman":"Aaju aayodhan mai tum ko hani ho tumree sabh hee pritnaa ko |","meaning_en":"","page":531},{"gurmukhi":"ਜਉ ਰੇ ਕੋਊ ਤੁਮ ਮੈ ਭਟ ਹੈ ਬਹੁ ਆਵਤ ਹੈ ਬਿਧਿ ਆਹਵ ਜਾ ਕੋ।","roman":"Jau re ko'oo tum mai bhat hai bahu aavat hai bidhi aahav jaa ko |","meaning_en":"","page":531},{"gurmukhi":"ਸੋ ਹਮਰੇ ਸੰਗ ਆਇ ਭਿਰੇ ਨ ਲਰੈ ਪਰਮੇਸੁਰ ਕੀ ਸਹੁ ਤਾ ਕੋ।","roman":"So hamre sang aai bhire na larai parmesur kee sahu taa ko |","meaning_en":"","page":531},{"gurmukhi":"ਜੋ ਟਰਿ ਹੈ ਇਹ ਆਹਵ ਤੇ ਸੋਈ ਸਿੰਘ ਨਹੀ ਭਟ ਸ੍ਯਾਰ ਕਹਾ ਕੋ। ੧੨੧੭।","roman":"Jo tari hai ih aahav te soee singh nahee bhat syaar kahaa ko | 1217 |","meaning_en":"","page":531}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":531},{"type":"verse","number":[1218],"number_text":"੧੨੧੮।","page":531,"lines":[{"gurmukhi":"ਅਮਿਟ ਸਿੰਘ ਕੇ ਬਚਨ ਸੁਨਿ ਹਰਿ ਜੂ ਕ੍ਰੋਧ ਬਢਾਇ।","roman":"Amit singh ke bachan suni hari joo krodh badhaai |","meaning_en":"","page":531},{"gurmukhi":"ਸਸਤ੍ਰ ਸਬੈ ਕਰ ਮੈ ਲਏ ਸਨਮੁਖਿ ਬਹੁਚਿਯੋ ਧਾਇ। ੧੨੧੮।","roman":"Sasatr sabai kar mai lae sanmukhi bahuchiyo dhaai | 1218 |","meaning_en":"","page":531}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":531},{"type":"verse","number":[1219],"number_text":"੧੨੧੯।","page":531,"lines":[{"gurmukhi":"ਆਵਤ ਸ੍ਯਾਮ ਕੋ ਪੇਖਿ ਬਲੀ ਅਪੁਨੇ ਮਨ ਮੈ ਅਤਿ ਕੋਪ ਬਢਾਯੋ।","roman":"Aavat syaam ko pekhi balee apune man mai ati kop badhaayo |","meaning_en":"","page":531},{"gurmukhi":"ਚਾਰੋ ਈ ਘੋਰਨਿ ਘਾਇਲ ਕੈ ਸਰ ਤੀਛਨ ਦਾਰੁਕ ਕੇ ਉਰਿ ਲਾਯੋ।","roman":"Chaaro ee ghorni ghaail kai sar teechhan daaruk ke uri laayo |","meaning_en":"","page":531},{"gurmukhi":"ਦੂਸਰੇ ਤੀਰ ਸੋ ਕਾਨ੍ਹ ਸਰੀਰ ਸੁ ਕੋਪ ਹਨ੍ਯੋ ਜੋਊ ਠਉਰ ਤਕਾਯੋ।","roman":"Doosre teer so kaanh sareer su kop hanyo jo'oo thaur takaayo |","meaning_en":"","page":531},{"gurmukhi":"ਸ੍ਯਾਮ ਕਹੈ ਅਮਿਟੇਸ ਮਨੋ ਜਦੁਬੀਰ ਕੀ ਦੇਹ ਕੋ ਲਛ ਬਨਾਯੋ। ੧੨੧੯।","roman":"Syaam kahai amites mano jadubeer kee deh ko lachh banaayo | 1219 |","meaning_en":"","page":531}]},{"type":"verse","number":[1220],"number_text":"੧੨੨੦।","page":531,"lines":[{"gurmukhi":"ਬਾਨ ਚਲਾਇ ਘਨੇ ਹਰਿ ਕੋ ਇਕ ਲੈ ਸਰ ਤੀਛਨ ਔਰ ਚਲਾਯੋ।","roman":"Baan chalaai ghane hari ko ik lai sar teechhan aur chalaayo |","meaning_en":"","page":531},{"gurmukhi":"ਲਾਗਤ ਸ੍ਯਾਮ ਗਿਰਿਓ ਰਥ ਮੈ ਰਨ ਛਾਡਿ ਕੈ ਦਾਰੁਕ ਸੂਤ ਪਰਾਯੋ।","roman":"Laagat syaam girio rath mai ran chhaadi kai daaruk soot paraayo |","meaning_en":"","page":531},{"gurmukhi":"ਦੇਖ ਕੈ ਭੂਪ ਭਜਿਯੋ ਬਲਬੀਰ ਨਿਹਾਰਿ ਚਮੂੰ ਤਿਹ ਊਪਰ ਧਾਯੋ।","roman":"Dekh kai bhoop bhajiyo balbeer nihaari chamoon tih oopar dhaayo |","meaning_en":"","page":531},{"gurmukhi":"ਮਾਨਹੁ ਹੇਰਿ ਬਡੇ ਸਰ ਕੋ ਗਜਰਾਜ ਕਵੀ ਗਨ ਰੌਦਨ ਆਯੋ। ੧੨੨੦।","roman":"Maanhu heri bade sar ko gajraaj kavee gan raudan aayo | 1220 |","meaning_en":"","page":531}]},{"type":"verse","number":[1221],"number_text":"੧੨੨੧।","page":531,"lines":[{"gurmukhi":"ਆਵਤ ਦੇਖਿ ਹਲੀ ਅਰਿ ਕੋ ਸੁ ਧਵਾਇ ਕੈ ਸ੍ਯੰਦਨ ਸਾਮੁਹੇ ਆਯੋ।","roman":"Aavat dekhi halee ari ko su dhavaai kai syandan saamuhe aayo |","meaning_en":"","page":531},{"gurmukhi":"ਤਾਨਿ ਲੀਯੋ ਧਨੁ ਕੋ ਕਰ ਮੈ ਸਰ ਕੋ ਧਰ ਕੈ ਅਰਿ ਓਰਿ ਚਲਾਯੋ।","roman":"Taani leeyo dhanu ko kar mai sar ko dhar kai ari ori chalaayo |","meaning_en":"","page":531},{"gurmukhi":"ਸੋ ਅਮਿਟੇਸ ਜੂ ਨੈਨ ਨਿਹਾਰਿ ਸੁ ਆਵਤ ਬਾਨ ਸੁ ਕਾਟਿ ਗਿਰਾਯੋ।","roman":"So amites joo nain nihaari su aavat baan su kaati giraayo |","meaning_en":"","page":531},{"gurmukhi":"ਆਇ ਭਿਰਿਯੋ ਬਲ ਸਿਉ ਤਬ ਹੀ ਅਪੁਨੇ ਜੀਯ ਮੈ ਅਤਿ ਕੋਪੁ ਬਢਾਯੋ। ੧੨੨੧।","roman":"Aai bhiriyo bal siu tab hee apune jeey mai ati kopu badhaayo | 1221 |","meaning_en":"","page":531}]},{"type":"verse","number":[1222],"number_text":"੧੨੨੨।","page":532,"lines":[{"gurmukhi":"ਕਾਟਿ ਧੁਜਾ ਰਥੁ ਕਾਟਿ ਦਯੋ ਅਸਿ ਚਾਪ ਕੋ ਕਾਟਿ ਜੁਦਾ ਕਰਿ ਡਾਰਿਓ।","roman":"Kaati dhujaa rathu kaati dayo asi chaap ko kaati judaa kari daario |","meaning_en":"","page":532},{"gurmukhi":"ਮੂਸਲ ਅਉ ਹਲ ਕਾਟਿ ਦਯੋ ਬਿਨੁ ਆਯੁਧ ਹੁਇ ਬਲਦੇਵ ਪਧਾਰਿਓ।","roman":"Moosal au hal kaati dayo binu aayudh hui baldev padhaario |","meaning_en":"","page":532},{"gurmukhi":"ਜਾਤ ਕਹਾ ਮੁਸਲੀ ਭਜਿ ਕੈ ਕਬਿ ਰਾਮ ਕਹੈ ਇਹ ਭਾਤਿ ਉਚਾਰਿਓ।","roman":"Jaat kahaa muslee bhaji kai kabi raam kahai ih bhaati uchaario |","meaning_en":"","page":532},{"gurmukhi":"ਯੌ ਕਹਿ ਕੈ ਅਸਿ ਕੋ ਗਹਿ ਕੈ ਲਹਿ ਕੈ ਦਲ ਜਾਦਵ ਕੋ ਲਲਕਾਰਿਓ। ੧੨੨੨।","roman":"Yau kahi kai asi ko gahi kai lahi kai dal jaadav ko lalkaario | 1222 |","meaning_en":"","page":532}]},{"type":"verse","number":[1223],"number_text":"੧੨੨੩।","page":532,"lines":[{"gurmukhi":"ਜੋ ਇਹ ਸਾਮੁਹੇ ਆਇ ਭਿਰੈ ਭਟ ਤਾ ਹੀ ਸੰਘਾਰ ਕੈ ਭੂਮਿ ਗਿਰਾਵੈ।","roman":"Jo ih saamuhe aai bhirai bhat taa hee sanghaar kai bhoomi giraavai |","meaning_en":"","page":532},{"gurmukhi":"ਕਾਨ ਪ੍ਰਮਾਨ ਲਉ ਤਾਨਿ ਕਮਾਨ ਘਨੇ ਸਰ ਸਤ੍ਰਨ ਕੇ ਤਨ ਲਾਵੈ।","roman":"Kaan pramaan lau taani kamaan ghane sar satran ke tan laavai |","meaning_en":"","page":532},{"gurmukhi":"ਸੋਊ ਬਚੇ ਤਿਹ ਤੇ ਬਲ ਬੀਰ ਜੋਊ ਭਜਿ ਆਪਨੇ ਪ੍ਰਾਨ ਬਚਾਵੈ।","roman":"So'oo bache tih te bal beer jo'oo bhaji aapne praan bachaavai |","meaning_en":"","page":532},{"gurmukhi":"ਅਉਰਨ ਕੀ ਸੁ ਕਹਾ ਗਨਤੀ ਜੁ ਬਡੇ ਭਟ ਜੀਵਤ ਜਾਨ ਨ ਪਾਵੈ। ੧੨੨੩।","roman":"Auran kee su kahaa gantee ju bade bhat jeevat jaan na paavai | 1223 |","meaning_en":"","page":532}]},{"type":"verse","number":[1224],"number_text":"੧੨੨੪।","page":532,"lines":[{"gurmukhi":"ਮੂਸਲ ਅਉਰ ਲਏ ਮੁਸਲੀ ਚੜਿ ਸ੍ਯੰਦਨ ਪੈ ਬਹੁਰੋ ਫਿਰਿ ਧਾਯੋ।","roman":"Moosal aur lae muslee chari syandan pai bahuro phiri dhaayo |","meaning_en":"","page":532},{"gurmukhi":"ਆਵਤ ਹੀ ਬਲ ਕੈ ਨ੍ਰਿਪ ਸੋ ਚਤੁਰੰਗ ਪ੍ਰਕਾਰ ਕੋ ਜੁਧੁ ਮਚਾਯੋ।","roman":"Aavat hee bal kai nrip so chaturang prakaar ko judhu machaayo |","meaning_en":"","page":532},{"gurmukhi":"ਅਉਰ ਜਿਤੇ ਭਟ ਠਾਢੇ ਹੁਤੇ ਰਿਸ ਕੈ ਮੁਖਿ ਤੇ ਇਹ ਭਾਤਿ ਸੁਨਾਯੋ।","roman":"Aur jite bhat thaadhe hute ris kai mukhi te ih bhaati sunaayo |","meaning_en":"","page":532},{"gurmukhi":"ਜਾਨਿ ਨ ਦੇਹੁ ਅਰੇ ਅਰਿ ਕੋ ਸੁਨਿ ਕੈ ਹਰਿ ਕੇ ਦਲੁ ਕੋਪੁ ਬਢਾਯੋ। ੧੨੨੪।","roman":"Jaani na dehu are ari ko suni kai hari ke dalu kopu badhaayo | 1224 |","meaning_en":"","page":532}]},{"type":"verse","number":[1225],"number_text":"੧੨੨੫।","page":532,"lines":[{"gurmukhi":"ਐਸੇ ਹਲਾਯੁਧ ਕੋਪਿ ਕਹਿਯੋ ਤਬ ਜਾਦਵ ਬੀਰ ਸਬੈ ਮਿਲਿ ਧਾਏ।","roman":"Aise halaayudh kopi kahiyo tab jaadav beer sabai mili dhaae |","meaning_en":"","page":532},{"gurmukhi":"ਜੋ ਇਹ ਸਾਮੁਹੇ ਆਇ ਅਰੇ ਗ੍ਰਿਹ ਕੋ ਤੇਊ ਜੀਵਤ ਜਾਨਿ ਨ ਪਾਏ।","roman":"Jo ih saamuhe aai are grih ko teoo jeevat jaani na paae |","meaning_en":"","page":532},{"gurmukhi":"ਅਉਰ ਜਿਤੇ ਤਹ ਠਾਢੇ ਹੁਤੇ ਅਸਿ ਲੈ ਬਰਛੈ ਪਰਸੇ ਗਹਿ ਆਏ।","roman":"Aur jite tah thaadhe hute asi lai barchhai parse gahi aae |","meaning_en":"","page":532},{"gurmukhi":"ਤੇਊ ਭਿਰੇ ਜੋਊ ਲਾਜ ਭਰੇ ਅਰਿ ਕੋ ਬਰ ਕੈ ਤਿਨ ਘਾਇ ਲਗਾਏ। ੧੨੨੫।","roman":"Teoo bhire jo'oo laaj bhare ari ko bar kai tin ghaai lagaae | 1225 |","meaning_en":"","page":532}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":532},{"type":"verse","number":[1226],"number_text":"੧੨੨੬।","page":532,"lines":[{"gurmukhi":"ਅਮਿਟ ਸਿੰਘ ਅਤਿ ਕੋਪ ਹ੍ਵੈ ਅਮਿਤ ਚਲਾਏ ਬਾਨ।","roman":"Amit singh ati kop hvai amit chalaae baan |","meaning_en":"","page":532},{"gurmukhi":"ਹਰਿ ਸੈਨਾ ਤਮ ਜਿਉ ਭਜੀ ਸਰ ਮਾਨੋ ਕਰਿ ਭਾਨੁ। ੧੨੨੬।","roman":"Hari sainaa tam jiu bhajee sar maano kari bhaanu | 1226 |","meaning_en":"","page":532}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":532},{"type":"verse","number":[1227],"number_text":"੧੨੨੭।","page":532,"lines":[{"gurmukhi":"ਜਾਤ ਭਜੇ ਜਦਵੀਰ ਪ੍ਰਿਤਨਾ ਰਨ ਮੈ ਮੁਸਲੀ ਇਹ ਭਾਤਿ ਪਚਾਰੇ।","roman":"Jaat bhaje jadveer pritnaa ran mai muslee ih bhaati pachaare |","meaning_en":"","page":532},{"gurmukhi":"ਛਤ੍ਰਨਿ ਕੇ ਕੁਲ ਮੈ ਉਪਜੇ ਕਿਹ ਭਾਤਿ ਪਰਾਵਤ ਹੋ ਬਲੁ ਹਾਰੇ।","roman":"Chhatrani ke kul mai upje kih bhaati paraavat ho balu haare |","meaning_en":"","page":532},{"gurmukhi":"ਆਯੁਧ ਛਾਡਤ ਹੋ ਕਰ ਤੇ ਡਰੁ ਮਾਨਿ ਘਨੋ ਬਿਨ ਹੀ ਅਰਿ ਮਾਰੇ।","roman":"Aayudh chhaadat ho kar te daru maani ghano bin hee ari maare |","meaning_en":"","page":532},{"gurmukhi":"ਤ੍ਰਾਸ ਕਰੋ ਨ ਕਛੂ ਰਨ ਮੈ ਜਬ ਲਉ ਤਨ ਮੈ ਥਿਰੁ ਪ੍ਰਾਨ ਹਮਾਰੇ। ੧੨੨੭।","roman":"Traas karo na kachhoo ran mai jab lau tan mai thiru praan hamaare | 1227 |","meaning_en":"","page":532}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":532},{"type":"verse","number":[1228],"number_text":"੧੨੨੮।","page":532,"lines":[{"gurmukhi":"ਕੋਪ ਅਯੋਧਨ ਮੈ ਹਲੀ ਸੁਭਟਨਿ ਕਹਿਯੋ ਪਚਾਰਿ।","roman":"Kop ayodhan mai halee subhatni kahiyo pachaari |","meaning_en":"","page":532},{"gurmukhi":"ਅਮਿਟ ਸਿੰਘ ਕੋ ਘੇਰ ਕੈ ਕਹਿਯੋ ਲੇਹੁ ਤੁਮ ਮਾਰ। ੧੨੨੮।","roman":"Amit singh ko gher kai kahiyo lehu tum maar | 1228 |","meaning_en":"","page":532}]},{"type":"heading","kind":"speaker","name":"ਕਬਿਯੋ ਬਾਚ","gurmukhi":"ਕਬਿਯੋ ਬਾਚ","roman":"Kabiyo baach","meaning_en":"","page":533},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":533},{"type":"verse","number":[1229],"number_text":"੧੨੨੯।","page":533,"lines":[{"gurmukhi":"ਆਇਸ ਪਾਇ ਤਬੈ ਮੁਸਲੀ ਚਹੂੰ ਓਰ ਚਮੂੰ ਲਲਕਾਰ ਪਰੀ।","roman":"Aais paai tabai muslee chahoon or chamoon lalkaar paree |","meaning_en":"","page":533},{"gurmukhi":"ਅਤਿ ਕੋਪ ਭਰੀ ਅਪੁਨੇ ਮਨ ਮੈ ਅਮਿਟੇਸ ਕੇ ਸਾਮੁਹੇ ਆਇ ਅਰੀ।","roman":"Ati kop bharee apune man mai amites ke saamuhe aai aree |","meaning_en":"","page":533},{"gurmukhi":"ਬਹੁ ਜੁਧੁ ਅਯੋਧਨ ਬੀਚ ਭਯੋ ਕਬ ਸ੍ਯਾਮ ਕਹੈ ਨਹੀ ਨੈਕੁ ਡਰੀ।","roman":"Bahu judhu ayodhan beech bhayo kab syaam kahai nahee naiku daree |","meaning_en":"","page":533},{"gurmukhi":"ਨ੍ਰਿਪ ਬੀਰ ਸਰਾਸਨਿ ਲੈ ਕਰ ਬਾਨ ਘਨੀ ਪ੍ਰਿਤਨਾ ਬਿਨੁ ਪ੍ਰਾਨ ਕਰੀ। ੧੨੨੯।","roman":"Nrip beer saraasni lai kar baan ghanee pritnaa binu praan karee | 1229 |","meaning_en":"","page":533}]},{"type":"verse","number":[1230],"number_text":"੧੨੩੦।","page":533,"lines":[{"gurmukhi":"ਕਾਟਿ ਕਰੀ ਰਥ ਕਾਟਿ ਦਏ ਬਹੁ ਬੀਰ ਹਨੇ ਅਤਿ ਬਾਜ ਸੰਘਾਰੇ।","roman":"Kaati karee rath kaati dae bahu beer hane ati baaj sanghaare |","meaning_en":"","page":533},{"gurmukhi":"ਘਾਇਲ ਘੂਮਤ ਹੈ ਰਨ ਮੈ ਕਿਤਨੇ ਸਿਰ ਭੂਮਿ ਪਰੇ ਧਰ ਭਾਰੇ।","roman":"Ghaail ghoomat hai ran mai kitne sir bhoomi pare dhar bhaare |","meaning_en":"","page":533},{"gurmukhi":"ਜੀਵਤ ਜੇ ਤੇਊ ਆਯੁਧ ਲੈ ਨ ਡਰੇ ਅਰਿ ਊਪਰਿ ਘਾਇ ਪ੍ਰਹਾਰੇ।","roman":"Jeevat je teoo aayudh lai na dare ari oopri ghaai prahaare |","meaning_en":"","page":533},{"gurmukhi":"ਤਉ ਤਿਨ ਕੇ ਤਨ ਆਹਵ ਮੈ ਅਸਿ ਲੈ ਨ੍ਰਿਪ ਖੰਡਨ ਖੰਡ ਕੈ ਡਾਰੇ। ੧੨੩੦।","roman":"Tau tin ke tan aahav mai asi lai nrip khandan khand kai daare | 1230 |","meaning_en":"","page":533}]},{"type":"verse","number":[1231],"number_text":"੧੨੩੧।","page":533,"lines":[{"gurmukhi":"ਜੁਧ ਬਿਖੈ ਅਤਿ ਤੀਰ ਲਗੇ ਬਹੁ ਬੀਰਨ ਕੋ ਤਨ ਸ੍ਰੋਣਤ ਭੀਨੇ।","roman":"Judh bikhai ati teer lage bahu beeran ko tan sronat bheene |","meaning_en":"","page":533},{"gurmukhi":"ਕਾਇਰ ਭਾਜ ਗਏ ਰਨ ਤੇ ਅਤਿ ਹੀ ਡਰ ਸਿਉ ਜਿਹ ਗਾਤ ਪਸੀਨੇ।","roman":"Kaair bhaaj gae ran te ati hee dar siu jih gaat paseene |","meaning_en":"","page":533},{"gurmukhi":"ਭੂਤ ਪਿਸਾਚ ਕਰੈ ਕਿਲਕਾਰ ਫਿਰੈ ਰਨ ਜੋਗਿਨ ਖਪਰ ਲੀਨੇ।","roman":"Bhoot pisaach karai kilkaar phirai ran jogin khapar leene |","meaning_en":"","page":533},{"gurmukhi":"ਆਨਿ ਫਿਰਿਓ ਤਹ ਸ੍ਰੀ ਤ੍ਰਿਪੁਰਾਰਿ ਸੁ ਆਧੋਈ ਅੰਗ ਸਿਵਾ ਤਨ ਕੀਨੇ। ੧੨੩੧।","roman":"Aani phirio tah sree tripuraari su aadhoee ang sivaa tan keene | 1231 |","meaning_en":"","page":533}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":533},{"type":"verse","number":[1232],"number_text":"੧੨੩੨।","page":533,"lines":[{"gurmukhi":"ਮੂਰਛਾ ਤੇ ਪਾਛੇ ਘਰੀ ਤੀਨਿ ਭਏ ਹਰਿ ਚੇਤ।","roman":"Moorchhaa te paachhe gharee teeni bhae hari chet |","meaning_en":"","page":533},{"gurmukhi":"ਦਾਰੁਕ ਸੋ ਕਹਿਓ ਹਾਕਿ ਰਥੁ ਪੁਨਿ ਆਏ ਜਹ ਖੇਤੁ। ੧੨੩੨।","roman":"Daaruk so kahio haaki rathu puni aae jah khetu | 1232 |","meaning_en":"","page":533}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":533},{"type":"verse","number":[1233],"number_text":"੧੨੩੩।","page":533,"lines":[{"gurmukhi":"ਜਾਨੋ ਸਹਾਇ ਭਯੋ ਹਰਿ ਕੋ ਬਹੁਰੋ ਜਦੁ ਬੰਸਨਿ ਕੋਪ ਜਗਿਯੋ।","roman":"Jaano sahaai bhayo hari ko bahuro jadu bansni kop jagiyo |","meaning_en":"","page":533},{"gurmukhi":"ਅਮਿਟੇਸ ਸੋ ਧਾਇ ਅਰੇ ਰਨ ਮੈ ਤਿਹ ਜੋਧਨ ਸੋ ਨਹੀ ਏਕ ਭਗਿਯੋ।","roman":"Amites so dhaai are ran mai tih jodhan so nahee ek bhagiyo |","meaning_en":"","page":533},{"gurmukhi":"ਗਹਿ ਬਾਨ ਕਮਾਨ ਕ੍ਰਿਪਾਨ ਗਦਾ ਅਤਿ ਹੀ ਦਲੁ ਆਹਵ ਕੋ ਉਮਗਿਯੋ।","roman":"Gahi baan kamaan kripaan gadaa ati hee dalu aahav ko umgiyo |","meaning_en":"","page":533},{"gurmukhi":"ਬਹੁ ਸ੍ਰਉਨ ਪਗੇ ਰੰਗਿ ਸ੍ਯਾਮ ਜਗੇ ਮਨੋ ਆਗਿ ਲਗੇ ਗਨ ਸਾਲ ਦਗਿਯੋ। ੧੨੩੩।","roman":"Bahu sraun page rangi syaam jage mano aagi lage gan saal dagiyo | 1233 |","meaning_en":"","page":533}]},{"type":"verse","number":[1234],"number_text":"੧੨੩੪।","page":533,"lines":[{"gurmukhi":"ਬਿਬਿਧਾਯੁਧ ਲੈ ਪੁਨਿ ਜੁਧੁ ਕੀਓ ਅਤਿ ਹੀ ਮਨ ਮੈ ਭਟ ਕੋਪ ਭਰੇ।","roman":"Bibidhaayudh lai puni judhu keeo ati hee man mai bhat kop bhare |","meaning_en":"","page":533},{"gurmukhi":"ਮੁਖ ਤੇ ਕਹਿ ਮਾਰੁ ਹੀ ਮਾਰ ਪਰੇ ਲਖਿ ਕੈ ਰਨ ਕਉ ਨਹੀ ਨੈਕੁ ਡਰੇ।","roman":"Mukh te kahi maaru hee maar pare lakhi kai ran kau nahee naiku dare |","meaning_en":"","page":533},{"gurmukhi":"ਪੁਨਿ ਯਾ ਬਿਧਿ ਸਿਉ ਕਬਿ ਰਾਮੁ ਕਹੈ ਜਦੁਬੀਰ ਘਨੇ ਅਰਿ ਸਾਥ ਅਰੇ।","roman":"Puni yaa bidhi siu kabi raamu kahai jadubeer ghane ari saath are |","meaning_en":"","page":533},{"gurmukhi":"ਰਿਸਿ ਭੂਪ ਤਬੈ ਬਲ ਕੈ ਅਸਿ ਲੈ ਰਿਪੁ ਕੇ ਤਨ ਦ੍ਵੈ ਕਰਿ ਚਾਰ ਕਰੇ। ੧੨੩੪।","roman":"Risi bhoop tabai bal kai asi lai ripu ke tan dvai kari chaar kare | 1234 |","meaning_en":"","page":533}]},{"type":"verse","number":[1235],"number_text":"੧੨੩੫।","page":534,"lines":[{"gurmukhi":"ਐਸੀ ਨਿਹਾਰਿ ਕੈ ਮਾਰਿ ਮਚੀ ਜੋਊ ਜੀਵਤ ਥੇ ਤਜਿ ਜੁਧੁ ਪਰਾਨੇ।","roman":"Aisee nihaari kai maari machee jo'oo jeevat the taji judhu paraane |","meaning_en":"","page":534},{"gurmukhi":"ਸ੍ਯਾਮ ਭਨੇ ਅਮਿਟੇਸ ਕੇ ਸਾਮੁਹੇ ਆਹਵ ਮੈ ਕੋਊ ਨ ਠਹਿਰਾਨੇ।","roman":"Syaam bhane amites ke saamuhe aahav mai ko'oo na thahiraane |","meaning_en":"","page":534},{"gurmukhi":"ਜੇ ਬਰ ਬੀਰ ਕਹਾਵਤ ਹੈ ਬਹੁ ਬਾਰ ਭਿਰੇ ਰਨਿ ਬਾਧਿਤ ਬਾਨੇ।","roman":"Je bar beer kahaavat hai bahu baar bhire rani baadhit baane |","meaning_en":"","page":534},{"gurmukhi":"ਸੋ ਇਹ ਭਾਤਿ ਚਲੇ ਭਜਿ ਕੈ ਜਿਮ ਪਉਨ ਬਹੇ ਦ੍ਰੁਮ ਪਾਤ ਉਡਾਨੇ। ੧੨੩੫।","roman":"So ih bhaati chale bhaji kai jim paun bahe drum paat udaane | 1235 |","meaning_en":"","page":534}]},{"type":"verse","number":[1236],"number_text":"੧੨੩੬।","page":534,"lines":[{"gurmukhi":"ਕੇਤੇ ਰਹੇ ਰਨ ਮੈ ਰੁਪ ਕੈ ਕਿਤਨੇ ਭਜਿ ਸ੍ਯਾਮ ਕੇ ਤੀਰ ਪੁਕਾਰੇ।","roman":"Kete rahe ran mai rup kai kitne bhaji syaam ke teer pukaare |","meaning_en":"","page":534},{"gurmukhi":"ਬੀਰ ਘਨੇ ਨਹੀ ਜਾਤ ਗਨੇ ਅਮਿਟੇਸਿ ਬਲੀ ਰਿਸ ਸਾਥਿ ਸੰਘਾਰੇ।","roman":"Beer ghane nahee jaat gane amitesi balee ris saathi sanghaare |","meaning_en":"","page":534},{"gurmukhi":"ਬਾਜ ਮਰੇ ਗਜ ਰਾਜ ਪਰੇ ਸੁ ਕਹੂੰ ਰਥ ਕਾਟਿ ਕੈ ਭੂ ਪਰਿ ਡਾਰੇ।","roman":"Baaj mare gaj raaj pare su kahoon rath kaati kai bhoo pari daare |","meaning_en":"","page":534},{"gurmukhi":"ਆਵਤ ਕਾ ਤੁਮਰੇ ਮਨ ਮੈ ਕਰਤਾ ਹਰਤਾ ਪ੍ਰਤਿਪਾਲਨ ਹਾਰੇ। ੧੨੩੬।","roman":"Aavat kaa tumre man mai kartaa hartaa pratipaalan haare | 1236 |","meaning_en":"","page":534}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":534},{"type":"verse","number":[1237],"number_text":"੧੨੩੭।","page":534,"lines":[{"gurmukhi":"ਰਨ ਆਤੁਰ ਹ੍ਵੈ ਸੁਭਟ ਜੋ ਹਰਿ ਸੋ ਬਿਨਤੀ ਕੀਨ।","roman":"Ran aatur hvai subhat jo hari so bintee keen |","meaning_en":"","page":534},{"gurmukhi":"ਤਬ ਤਿਨ ਕੋ ਬ੍ਰਿਜਰਾਜ ਜੂ ਇਹ ਬਿਧਿ ਉਤਰ ਦੀਨ। ੧੨੩੭।","roman":"Tab tin ko brijraaj joo ih bidhi utar deen | 1237 |","meaning_en":"","page":534}]},{"type":"heading","kind":"speaker","name":"ਕਾਨ੍ਹ ਜੂ ਬਾਚ","gurmukhi":"ਕਾਨ੍ਹ ਜੂ ਬਾਚ","roman":"Kaanh joo baach","meaning_en":"","page":534},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":534},{"type":"verse","number":[1238],"number_text":"੧੨੩੮।","page":534,"lines":[{"gurmukhi":"ਨਿਧਿ ਬਾਰਿ ਬਿਖੈ ਅਤਿ ਹੀ ਹਠ ਕੈ ਬਹੁ ਮਾਸ ਰਹਿਯੋ ਤਪੁ ਜਾਪੁ ਕੀਓ।","roman":"Nidhi baari bikhai ati hee hath kai bahu maas rahiyo tapu jaapu keeo |","meaning_en":"","page":534},{"gurmukhi":"ਬਹੁਰੋ ਤਜਿ ਕੈ ਪਿਤ ਮਾਤ ਸੁ ਭ੍ਰਾਤ ਅਵਾਸ ਤਜਿਯੋ ਬਨਬਾਸ ਲੀਓ।","roman":"Bahuro taji kai pit maat su bhraat avaas tajiyo banbaas leeo |","meaning_en":"","page":534},{"gurmukhi":"ਸਿਵ ਰੀਝਿ ਤਪੋਧਨ ਮੈ ਇਹ ਕੋ ਕਹਿਯੋ ਮਾਗ ਮਹਾ ਬਰੁ ਤੋਹਿ ਦੀਓ।","roman":"Siv reejhi tapodhan mai ih ko kahiyo maag mahaa baru tohi deeo |","meaning_en":"","page":534},{"gurmukhi":"ਮੁਹਿ ਸਾਮੁਹੇ ਕੋਊ ਨ ਸਤ੍ਰ ਰਹੈ ਬਰੁ ਦੇਹੁ ਇਹੈ ਮੁਖਿ ਮਾਗ ਲੀਓ। ੧੨੩੮।","roman":"Muhi saamuhe ko'oo na satr rahai baru dehu ihai mukhi maag leeo | 1238 |","meaning_en":"","page":534}]},{"type":"verse","number":[1239],"number_text":"੧੨੩੯।","page":534,"lines":[{"gurmukhi":"ਸੇਸ ਸੁਰੇਸ ਗਣੇਸ ਨਿਸੇਸ ਦਿਨੇਸ ਹੂੰ ਤੇ ਨਹੀ ਜਾਇ ਸੰਘਾਰਿਓ।","roman":"Ses sures ganes nises dines hoon te nahee jaai sanghaario |","meaning_en":"","page":534},{"gurmukhi":"ਸੋ ਬਰ ਪਾਇ ਮਹਾਸਿਵ ਤੇ ਅਰਿ ਬ੍ਰਿੰਦ ਨਰਿੰਦ ਇਹੀ ਰਨਿ ਮਾਰਿਓ।","roman":"So bar paai mahaasiv te ari brind narind ihee rani maario |","meaning_en":"","page":534},{"gurmukhi":"ਸੂਰਨ ਸੋ ਬਲਬੀਰ ਤਬੈ ਅਪੁਨੈ ਮੁਖਿ ਤੇ ਇਹ ਭਾਤਿ ਉਚਾਰਿਓ।","roman":"Sooran so balbeer tabai apunai mukhi te ih bhaati uchaario |","meaning_en":"","page":534},{"gurmukhi":"ਹਉ ਤਿਹ ਸੰਗਰ ਕੇ ਸਮੁਹੇ ਮ੍ਰਿਤ ਕੀ ਬਿਧਿ ਪੂਛਿ ਇਹੀ ਜੀਯ ਧਾਰਿਓ। ੧੨੩੯।","roman":"Hau tih sangar ke samuhe mrit kee bidhi poochhi ihee jeey dhaario | 1239 |","meaning_en":"","page":534}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":534},{"type":"verse","number":[1240],"number_text":"੧੨੪੦।","page":534,"lines":[{"gurmukhi":"ਜਬ ਹਰਿ ਜੂ ਐਸੇ ਕਹਿਯੋ ਤਬ ਮੁਸਲੀ ਸੁਨਿ ਪਾਇ।","roman":"Jab hari joo aise kahiyo tab muslee suni paai |","meaning_en":"","page":534},{"gurmukhi":"ਇਹ ਕੋ ਅਬ ਹੀ ਹਉ ਹਨੋ ਬੋਲਿਯੋ ਬਚਨੁ ਰਿਸਾਇ। ੧੨੪੦।","roman":"Ih ko ab hee hau hano boliyo bachnu risaai | 1240 |","meaning_en":"","page":534}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":534},{"type":"verse","number":[1241],"number_text":"੧੨੪੧।","page":534,"lines":[{"gurmukhi":"ਕੋਪ ਹਲੀ ਜਦੁਬੀਰ ਹੀ ਸੋ ਇਹ ਭਾਤਿ ਕਹਿਯੋ ਕਹੋ ਜਾਇ ਸੰਘਾਰੋ।","roman":"Kop halee jadubeer hee so ih bhaati kahiyo kaho jaai sanghaaro |","meaning_en":"","page":534},{"gurmukhi":"ਜਉ ਸਿਵ ਆਇ ਸਹਾਇ ਕਰੈ ਸਿਵ ਕੋ ਰਨ ਮੈ ਤਿਹ ਸੰਗ ਪ੍ਰਹਾਰੋ।","roman":"Jau siv aai sahaai karai siv ko ran mai tih sang prahaaro |","meaning_en":"","page":534},{"gurmukhi":"ਸਾਚ ਕਹੋ ਪ੍ਰਭ ਜੂ ਤੁਮ ਸੋ ਹਨਿ ਹੋ ਅਮਿਟੇਸ ਨਹੀ ਬਲ ਹਾਰੋ।","roman":"Saach kaho prabh joo tum so hani ho amites nahee bal haaro |","meaning_en":"","page":535},{"gurmukhi":"ਪਉਨ ਸਰੂਪ ਸਹਾਇ ਕਰੋ ਤੁਮ ਪਾਵਕ ਹੁਇ ਰਿਪੁ ਕਾਨਨ ਜਾਰੋ। ੧੨੪੧।","roman":"Paun saroop sahaai karo tum paavak hui ripu kaanan jaaro | 1241 |","meaning_en":"","page":535}]},{"type":"heading","kind":"speaker","name":"ਕ੍ਰਿਸਨ ਬਾਚ ਮੁਸਲੀ ਸੋ","gurmukhi":"ਕ੍ਰਿਸਨ ਬਾਚ ਮੁਸਲੀ ਸੋ","roman":"Krisan baach muslee so","meaning_en":"","page":535},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":535},{"type":"verse","number":[1242],"number_text":"੧੨੪੨।","page":535,"lines":[{"gurmukhi":"ਤੁਮ ਸੋ ਤਿਨਿ ਜਬ ਜੁਧ ਕੀਆ ਕਿਉ ਨ ਲਰੇ ਪਗ ਰੋਪਿ।","roman":"Tum so tini jab judh keeaa kiu na lare pag ropi |","meaning_en":"","page":535},{"gurmukhi":"ਅਬ ਹਮ ਆਗੇ ਗਰਬ ਕੋ ਬਚਨ ਉਚਾਰਤ ਕੋਪਿ। ੧੨੪੨।","roman":"Ab ham aage garab ko bachan uchaarat kopi | 1242 |","meaning_en":"","page":535}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":535},{"type":"verse","number":[1243],"number_text":"੧੨੪੩।","page":535,"lines":[{"gurmukhi":"ਜਾਦਵ ਭਾਜਿ ਗਏ ਸਿਗਰੇ ਤੁਮ ਬੋਲਤ ਹੋ ਅਹੰਕਾਰਨਿ ਜਿਉ।","roman":"Jaadav bhaaji gae sigre tum bolat ho ahankaarni jiu |","meaning_en":"","page":535},{"gurmukhi":"ਅਬ ਆਜ ਹਨੋ ਅਰਿ ਕੋ ਰਨ ਮੈ ਕਸ ਭਾਖਤ ਹੋ ਮਤਵਾਰਿਨ ਜਿਉ।","roman":"Ab aaj hano ari ko ran mai kas bhaakhat ho matvaarin jiu |","meaning_en":"","page":535},{"gurmukhi":"ਤਿਹ ਕੋ ਬਡਵਾਨਲ ਕੇ ਪਰਸੇ ਜਰ ਜੈਹੋ ਤਬੈ ਤ੍ਰਿਨ ਭਾਰਨ ਜਿਉ।","roman":"Tih ko badvaanal ke parse jar jaiho tabai trin bhaaran jiu |","meaning_en":"","page":535},{"gurmukhi":"ਜਦੁਬੀਰ ਕਹਿਯੋ ਵਹੁ ਕੇਹਰਿ ਹੈ ਤਿਹ ਤੇ ਭਜਿ ਹੋ ਬਲਿ ਬਾਰੁਨ ਜਿਉ। ੧੨੪੩।","roman":"Jadubeer kahiyo vahu kehri hai tih te bhaji ho bali baarun jiu | 1243 |","meaning_en":"","page":535}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":535},{"type":"verse","number":[1244],"number_text":"੧੨੪੪।","page":535,"lines":[{"gurmukhi":"ਬ੍ਰਿਜ ਭੂਖਨ ਬਲਭਦ੍ਰ ਸੋ ਇਹ ਬਿਧਿ ਕਹੀ ਸੁਨਾਇ।","roman":"Brij bhookhan balbhadr so ih bidhi kahee sunaai |","meaning_en":"","page":535},{"gurmukhi":"ਹਰੈ ਬੋਲਿ ਬਲਿ ਯੌ ਕਹਿਯੋ ਕਰੋ ਜੁ ਪ੍ਰਭਹਿ ਸੁਹਾਇ। ੧੨੪੪।","roman":"Harai boli bali yau kahiyo karo ju prabhhi suhaai | 1244 |","meaning_en":"","page":535}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":535},{"type":"verse","number":[1245],"number_text":"੧੨੪੫।","page":535,"lines":[{"gurmukhi":"ਯੌ ਬਲਿ ਸਿਉ ਕਹਿਯੋ ਰੋਸ ਬਢਾਇ ਚਲਿਯੋ ਹਰਿ ਜੂ ਹਥਿਯਾਰ ਸੰਭਾਰੇ।","roman":"Yau bali siu kahiyo ros badhaai chaliyo hari joo hathiyaar sanbhaare |","meaning_en":"","page":535},{"gurmukhi":"ਕਾਇਰ ਜਾਤ ਕਹਾ ਥਿਰੁ ਹੋਹੁ ਸੁ ਕੇਹਰਿ ਜ੍ਯੋ ਹਰਿ ਜੂ ਭਭਕਾਰੇ।","roman":"Kaair jaat kahaa thiru hohu su kehri jyo hari joo bhabhkaare |","meaning_en":"","page":535},{"gurmukhi":"ਬਾਨ ਅਨੇਕ ਹਨੇ ਉਨ ਹੂੰ ਹਰਿ ਕੋਪ ਹੁਇ ਬਾਨ ਸੋ ਬਾਨ ਨਿਵਾਰੇ।","roman":"Baan anek hane un hoon hari kop hui baan so baan nivaare |","meaning_en":"","page":535},{"gurmukhi":"ਅਪੁਨੇ ਪਾਨਿ ਲਯੋ ਧਨੁ ਤਾਨਿ ਘਨੇ ਸਰ ਲੈ ਅਰਿ ਊਪਰਿ ਡਾਰੇ। ੧੨੪੫।","roman":"Apune paani layo dhanu taani ghane sar lai ari oopri daare | 1245 |","meaning_en":"","page":535}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":535},{"type":"verse","number":[1246],"number_text":"੧੨੪੬।","page":535,"lines":[{"gurmukhi":"ਬਾਨ ਅਨੇਕ ਚਲਾਇ ਕੈ ਪੁਨਿ ਬੋਲੇ ਹਰਿ ਦੇਵ।","roman":"Baan anek chalaai kai puni bole hari dev |","meaning_en":"","page":535},{"gurmukhi":"ਅਮਿਟ ਸਿੰਘ ਮਿਟ ਜਾਇਗੋ ਝੂਠੋ ਤੁਯ ਅਹੰਮੇਵ। ੧੨੪੬।","roman":"Amit singh mit jaaigo jhootho tuy ahanmev | 1246 |","meaning_en":"","page":535}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":535},{"type":"verse","number":[1247],"number_text":"੧੨੪੭।","page":535,"lines":[{"gurmukhi":"ਹਉ ਜਬ ਜੁਧ ਕੇ ਕਾਜ ਚਲਿਓ ਤੁ ਅਕਾਲ ਕਹਿਯੋ ਹਰਿ ਜੂ ਹਮ ਸਉ।","roman":"Hau jab judh ke kaaj chalio tu akaal kahiyo hari joo ham sau |","meaning_en":"","page":535},{"gurmukhi":"ਤਿਹ ਕੋ ਕਹਿਯੋ ਕਾਨਿ ਕੀਯੋ ਤਬ ਮੈ ਤੁਅ ਹੇਰਿ ਕੈ ਆਯੋ ਹਉ ਅਪਨੀ ਗਉ।","roman":"Tih ko kahiyo kaani keeyo tab mai tua heri kai aayo hau apnee gau |","meaning_en":"","page":535},{"gurmukhi":"ਤਿਹ ਤੇ ਨ੍ਰਿਪ ਬੀਰ ਕਹਿਯੋ ਸੁਨਿ ਕੈ ਤਜਿ ਸੰਕ ਭਿਰੇ ਦੋਊ ਆਹਵ ਮਉ।","roman":"Tih te nrip beer kahiyo suni kai taji sank bhire do'oo aahav mau |","meaning_en":"","page":535},{"gurmukhi":"ਧੂਅ ਲੋਕ ਟਰੈ ਗਿਰਿ ਮੇਰੁ ਹਲੈ ਸੁ ਤਉ ਤੁਮ ਤੋ ਟਰਿਹੋ ਨਹੀ ਹਉ। ੧੨੪੭।","roman":"Dhooa lok tarai giri meru halai su tau tum to tariho nahee hau | 1247 |","meaning_en":"","page":535}]},{"type":"heading","kind":"speaker","name":"ਕਾਨ੍ਹ ਜੂ ਬਾਚ","gurmukhi":"ਕਾਨ੍ਹ ਜੂ ਬਾਚ","roman":"Kaanh joo baach","meaning_en":"","page":536},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":536},{"type":"verse","number":[1248],"number_text":"੧੨੪੮।","page":536,"lines":[{"gurmukhi":"ਕਹਿਯੋ ਕ੍ਰਿਸਨ ਤੁਹਿ ਮਾਰਿਹੋ ਤੂੰ ਕਰਿ ਕੋਟਿ ਉਪਾਇ।","roman":"Kahiyo krisan tuhi maariho toon kari koti upaai |","meaning_en":"","page":536},{"gurmukhi":"ਅਮਿਟ ਸਿੰਘ ਬੋਲਿਓ ਤਬਹਿ ਅਤਿ ਹੀ ਕੋਪੁ ਬਢਾਇ। ੧੨੪੮।","roman":"Amit singh bolio tabhi ati hee kopu badhaai | 1248 |","meaning_en":"","page":536}]},{"type":"heading","kind":"speaker","name":"ਅਮਿਟ ਸਿੰਘ ਬਾਚ","gurmukhi":"ਅਮਿਟ ਸਿੰਘ ਬਾਚ","roman":"Amit singh baach","meaning_en":"","page":536},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":536},{"type":"verse","number":[1249],"number_text":"੧੨੪੯।","page":536,"lines":[{"gurmukhi":"ਹਉ ਨ ਬਕੀ ਬਕ ਨੀਚ ਨਹੀ ਬ੍ਰਿਖਭਾਸੁਰ ਸੋ ਛਲ ਸਾਥਿ ਸੰਘਾਰਿਓ।","roman":"Hau na bakee bak neech nahee brikhbhaasur so chhal saathi sanghaario |","meaning_en":"","page":536},{"gurmukhi":"ਕੇਸੀ ਨ ਹਉ ਗਜ ਧੇਨੁਕ ਨਾਹਿ ਹਉ ਤ੍ਰਿਨਾਵ੍ਰਤ ਸਿਲਾ ਪਰਿ ਡਾਰਿਓ।","roman":"Kesee na hau gaj dhenuk naahi hau trinaavrat silaa pari daario |","meaning_en":"","page":536},{"gurmukhi":"ਹਉ ਨ ਅਘਾਸੁਰ ਮੁਸਟ ਚੰਡੂਰ ਸੁ ਕੰਸ ਨਹੀ ਗਹਿ ਕੇਸ ਪਛਾਰਿਓ।","roman":"Hau na aghaasur musat chandoor su kans nahee gahi kes pachhaario |","meaning_en":"","page":536},{"gurmukhi":"ਭ੍ਰਾਤ ਬਲੀ ਤੁਅ ਨਾਮ ਪਰਿਓ ਕਹੋ ਕਉਨ ਬਲੀ ਬਲੁ ਸੋ ਤੁਮ ਮਾਰਿਓ। ੧੨੪੯।","roman":"Bhraat balee tua naam pario kaho kaun balee balu so tum maario | 1249 |","meaning_en":"","page":536}]},{"type":"verse","number":[1250],"number_text":"੧੨੫੦।","page":536,"lines":[{"gurmukhi":"ਕਾ ਚਤੁਰਾਨਨ ਮੈ ਬਲੁ ਹੈ ਜੋਊ ਆਹਵ ਮੈ ਹਮ ਸੋ ਰਿਸ ਕੈ ਹੈ।","roman":"Kaa chaturaanan mai balu hai jo'oo aahav mai ham so ris kai hai |","meaning_en":"","page":536},{"gurmukhi":"ਕਉਨ ਖਗੇਸ ਗਨੇਸ ਦਿਨੇਸ ਨਿਸੇਸ ਨਿਹਾਰਿ ਕੈ ਮੋਨ ਭਜੈ ਹੈ।","roman":"Kaun khages ganes dines nises nihaari kai mon bhajai hai |","meaning_en":"","page":536},{"gurmukhi":"ਸੇਸ ਜਲੇਸ ਸੁਰੇਸ ਧਨੇਸ ਜੂ ਜਉ ਅਰਿ ਹੈ ਤਊ ਮੋਹ ਨ ਛੈ ਹੈ।","roman":"Ses jales sures dhanes joo jau ari hai taoo moh na chhai hai |","meaning_en":"","page":536},{"gurmukhi":"ਭਾਜਤ ਦੇਵ ਬਿਲੋਕ ਕੈ ਮੋ ਕਉ ਤੂ ਲਰਿਕਾ ਲਰਿ ਕਾ ਫਲੁ ਲੈ ਹੈ। ੧੨੫੦।","roman":"Bhaajat dev bilok kai mo kau too larikaa lari kaa phalu lai hai | 1250 |","meaning_en":"","page":536}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":536},{"type":"verse","number":[1251],"number_text":"੧੨੫੧।","page":536,"lines":[{"gurmukhi":"ਖੋਵਤ ਹੈ ਜੀਉ ਕਿਹ ਨਮਿਤ ਤਜਿ ਰਨਿ ਸ੍ਯਾਮ ਪਧਾਰੁ।","roman":"Khovat hai jeeu kih namit taji rani syaam padhaaru |","meaning_en":"","page":536},{"gurmukhi":"ਮਾਰਤ ਹੋ ਰਨਿ ਆਜ ਤੁਹਿ ਅਪਨੇ ਬਲਹਿ ਸੰਭਾਰ। ੧੨੫੧।","roman":"Maarat ho rani aaj tuhi apne balhi sanbhaar | 1251 |","meaning_en":"","page":536}]},{"type":"heading","kind":"speaker","name":"ਕਾਨ੍ਹ ਜੂ ਬਾਚ","gurmukhi":"ਕਾਨ੍ਹ ਜੂ ਬਾਚ","roman":"Kaanh joo baach","meaning_en":"","page":536},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":536},{"type":"verse","number":[1252],"number_text":"੧੨੫੨।","page":536,"lines":[{"gurmukhi":"ਅਮਿਟ ਸਿੰਘ ਕੇ ਬਚਨ ਸੁਨਿ ਬੋਲਿਯੋ ਹਰਿ ਕਰਿ ਕੋਪ।","roman":"Amit singh ke bachan suni boliyo hari kari kop |","meaning_en":"","page":536},{"gurmukhi":"ਅਬ ਅਕਾਰ ਤੁਅ ਲੋਪ ਕਰਿ ਅਮਿਟ ਸਿੰਘ ਬਿਨੁ ਓਪ। ੧੨੫੨।","roman":"Ab akaar tua lop kari amit singh binu op | 1252 |","meaning_en":"","page":536}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":536},{"type":"verse","number":[1253],"number_text":"੧੨੫੩।","page":536,"lines":[{"gurmukhi":"ਜੁਧੁ ਕਰਿਯੋ ਹਰਿ ਜੂ ਜੁਗ ਜਾਮ ਤਬੈ ਰਿਪੁ ਰੀਝ ਕੈ ਐਸੇ ਪੁਕਾਰਿਓ।","roman":"Judhu kariyo hari joo jug jaam tabai ripu reejh kai aise pukaario |","meaning_en":"","page":536},{"gurmukhi":"ਬਾਲਕ ਹੋ ਅਰੁ ਜੁਧ ਪ੍ਰਬੀਨ ਹੋ ਮਾਗੁ ਕਛੂ ਮੁਖਿ ਜੋ ਜੀਯ ਧਾਰਿਓ।","roman":"Baalak ho aru judh prabeen ho maagu kachhoo mukhi jo jeey dhaario |","meaning_en":"","page":536},{"gurmukhi":"ਆਪੁਨੀ ਪਾਤ ਕੀ ਘਾਤ ਕੀ ਬਾਤ ਕਉ ਦੇਹੁ ਬਤਾਇ ਮੁਰਾਰਿ ਉਚਾਰਿਓ।","roman":"Aapunee paat kee ghaat kee baat kau dehu bataai muraari uchaario |","meaning_en":"","page":536},{"gurmukhi":"ਸਾਮੁਹੇ ਮੋਹਿ ਨ ਕੋਊ ਹਨੈ ਅਸਿ ਲੈ ਤਬ ਕਾਨ੍ਹ ਪਛਾਵਰਿ ਝਾਰਿਓ। ੧੨੫੩।","roman":"Saamuhe mohi na ko'oo hanai asi lai tab kaanh pachhaavri jhaario | 1253 |","meaning_en":"","page":536}]},{"type":"verse","number":[1254],"number_text":"੧੨੫੪।","page":537,"lines":[{"gurmukhi":"ਸੀਸ ਕਟਿਓ ਨ ਹਟਿਓ ਤਿਹ ਠਉਰ ਤੇ ਦਉਰ ਕੈ ਆਗੈ ਹੀ ਕੋ ਪਗੁ ਧਾਰਿਓ।","roman":"Sees katio na hatio tih thaur te daur kai aagai hee ko pagu dhaario |","meaning_en":"","page":537},{"gurmukhi":"ਕੁੰਚਰ ਏਕ ਹੁਤੇ ਦਲ ਮੈ ਤਿਹ ਧਾਇ ਕੈ ਜਾਇ ਕੈ ਘਾਇ ਪ੍ਰਹਾਰਿਓ।","roman":"Kunchar ek hute dal mai tih dhaai kai jaai kai ghaai prahaario |","meaning_en":"","page":537},{"gurmukhi":"ਮਾਰਿ ਕਰੀ ਹਨਿ ਬੀਰ ਚਲਿਓ ਅਸਿ ਲੈ ਕਰਿ ਸ੍ਰੀ ਹਰਿ ਓਰਿ ਪਧਾਰਿਓ।","roman":"Maari karee hani beer chalio asi lai kari sree hari ori padhaario |","meaning_en":"","page":537},{"gurmukhi":"ਭੂਮਿ ਗਿਰਿਓ ਸਿਰੁ ਸ੍ਰੀ ਸਿਵ ਲੈ ਗੁਹਿ ਮੁੰਡ ਕੀ ਮਾਲ ਕੋ ਮੇਰੁ ਸਵਾਰਿਓ। ੧੨੫੪।","roman":"Bhoomi girio siru sree siv lai guhi mund kee maal ko meru savaario | 1254 |","meaning_en":"","page":537}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":537},{"type":"verse","number":[1255],"number_text":"੧੨੫੫।","page":537,"lines":[{"gurmukhi":"ਅਮਿਟ ਸਿੰਘ ਅਤਿ ਹੀ ਬਲੀ ਬਹੁਤੁ ਕਰਿਓ ਸੰਗ੍ਰਾਮ।","roman":"Amit singh ati hee balee bahutu kario sangraam |","meaning_en":"","page":537},{"gurmukhi":"ਨਿਕਸਿ ਜੋਤਿ ਹਰਿ ਸੌ ਮਿਲੀ ਜਿਉ ਨਿਸ ਕੋ ਕਰਿ ਭਾਨੁ। ੧੨੫੫।","roman":"Niksi joti hari sau milee jiu nis ko kari bhaanu | 1255 |","meaning_en":"","page":537}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":537},{"type":"verse","number":[1256],"number_text":"੧੨੫੬।","page":537,"lines":[{"gurmukhi":"ਅਉਰ ਜਿਤੀ ਪ੍ਰਿਤਨਾ ਅਰਿ ਕੀ ਤਿਨ ਹੂੰ ਜਦੁਬੀਰ ਸੋ ਜੁਧੁ ਕੀਆ।","roman":"Aur jitee pritnaa ari kee tin hoon jadubeer so judhu keeaa |","meaning_en":"","page":537},{"gurmukhi":"ਬਿਨੁ ਭੂਪਤਿ ਆਨਿ ਅਰੇ ਨ ਡਰੇ ਰਿਸ ਕੋ ਕਰਿ ਕੈ ਅਤਿ ਗਾਢੋ ਹੀਆ।","roman":"Binu bhoopti aani are na dare ris ko kari kai ati gaadho heeaa |","meaning_en":"","page":537},{"gurmukhi":"ਮਿਲ ਧਾਇ ਪਰੇ ਹਰਿ ਪੈ ਭਟ ਯੌ ਕਵਿ ਤਾ ਛਬਿ ਕੋ ਜਸੁ ਮਾਨ ਲੀਆ।","roman":"Mil dhaai pare hari pai bhat yau kavi taa chhabi ko jasu maan leeaa |","meaning_en":"","page":537},{"gurmukhi":"ਮਾਨੋ ਰਾਤਿ ਸਮੈ ਉਡਿ ਕੀਟ ਪਤੰਗ ਜਿਉ ਟੂਟਿ ਪਰੈ ਅਵਿਲੋਕਿ ਦੀਆ। ੧੨੫੬।","roman":"Maano raati samai udi keet patang jiu tooti parai aviloki deeaa | 1256 |","meaning_en":"","page":537}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":537},{"type":"verse","number":[1257],"number_text":"੧੨੫੭।","page":537,"lines":[{"gurmukhi":"ਤਬ ਬ੍ਰਿਜ ਭੂਖਨ ਖੜਗੁ ਗਹਿ ਅਰਿ ਬਹੁ ਦਏ ਗਿਰਾਇ।","roman":"Tab brij bhookhan khargu gahi ari bahu dae giraai |","meaning_en":"","page":537},{"gurmukhi":"ਏਕ ਅਰੇ ਇਕ ਰੁਪਿ ਲਰੇ ਇਕ ਰਨ ਛਾਡਿ ਪਰਾਇ। ੧੨੫੭।","roman":"Ek are ik rupi lare ik ran chhaadi paraai | 1257 |","meaning_en":"","page":537}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"","page":537},{"type":"verse","number":[1258],"number_text":"੧੨੫੮।","page":537,"lines":[{"gurmukhi":"ਅਮਿਟਸਿੰਘ ਦਲੁ ਹਰਿ ਜੂ ਹਯੋ। ਹਾਹਾਕਾਰ ਸਤ੍ਰੁ ਦਲਿ ਪਯੋ।","roman":"Amitsingh dalu hari joo hayo | haahaakaar satru dali payo |","meaning_en":"","page":537},{"gurmukhi":"ਉਤ ਤੇ ਸੂਰ ਅਸਤੁ ਹੋਇ ਗਯੋ। ਪ੍ਰਾਚੀ ਦਿਸ ਤੇ ਸਸਿ ਪ੍ਰਗਟਯੋ। ੧੨੫੮।","roman":"Ut te soor astu hoi gayo | praachee dis te sasi pragatyo | 1258 |","meaning_en":"","page":537}]},{"type":"verse","number":[1259],"number_text":"੧੨੫੯।","page":537,"lines":[{"gurmukhi":"ਚਾਰ ਜਾਮ ਦਿਨ ਜੁਧ ਸੁ ਕੀਨੋ। ਬੀਰਨ ਕੋ ਬਲੁ ਹੁਇ ਗਯੋ ਛੀਨੋ।","roman":"Chaar jaam din judh su keeno | beeran ko balu hui gayo chheeno |","meaning_en":"","page":537},{"gurmukhi":"ਦੋਊ ਦਲ ਆਪ ਆਪ ਮਿਲ ਧਾਏ। ਇਤ ਜਦੁਬੀਰ ਬਸਤ ਗ੍ਰਿਹਿ ਆਏ। ੧੨੫੯।","roman":"Do'oo dal aap aap mil dhaae | it jadubeer basat grihi aae | 1259 |","meaning_en":"","page":537}]}],"ending":{"lines":[{"gurmukhi":"ਇਤਿ ਸ੍ਰੀ ਬਚਿਤ੍ਰ ਨਾਟਕ ਗ੍ਰੰਥੇ ਕ੍ਰਿਸਨਾਵਤਾਰੇ ਜੁਧ ਪ੍ਰਬੰਧੇ ਅਮਿਟ ਸਿੰਘ","roman":"Iti sree bachitr naatak granthe krisnaavtaare judh prabandhe amit singh","meaning_en":"","page":537},{"gurmukhi":"ਸੈਨ ਸਹਤ ਬਧਹਿ ਧਯਾਇ ਸਮਾਪਤੰ।","roman":"Sain sahat badhhi dhayaai samaaptan |","meaning_en":"","page":537}],"page":537}});
